-- Actual photo alpha silhouettes; old attempts keep their original packs.
BEGIN;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"photo-size-v7-1","version":7,"kind":"scale","prompt":"Resize the nintendo switch to match its real size.","target":{"name":"Nintendo Switch","dimension":"width with Joy-Con","shape":"photo:switch"},"reference":{"name":"Bicycle master-link pliers","dimension":"reference overall length","shape":"photo:pliers","measure":"17 cm · reference overall length"},"bounds":[0.02,50],"answer":1.40588235,"explanation":"Nintendo Switch: 0.239 m (width with Joy-Con). Bicycle master-link pliers: 0.17 m (reference overall length). Ratio: 1.41×.\nOriginal Nintendo Switch: 239 mm wide with Joy-Con attached.\nA 17 cm pliers reference; tool models differ.","sources":["https://www.nintendo.com/us/gaming-systems/switch/tech-specs/","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:Nintendo-Switch-wJoyCons-BlRd-Standing-FL.png","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png"]},{"id":"photo-size-v7-2","version":7,"kind":"scale","prompt":"Resize the european badger to match its real size.","target":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger"},"reference":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller","measure":"5 m · reference overall length"},"bounds":[0.02,50],"answer":0.15,"explanation":"European badger: 0.75 m (reference head-and-body length). Road roller: 5 m (reference overall length). Ratio: 0.15×.\nA 75 cm adult reference, excluding the tail. Adults vary in size.\nA five-metre road-roller reference; construction machines come in many sizes.","sources":["https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png","https://commons.wikimedia.org/wiki/File:Road_roller.png"]},{"id":"photo-size-v7-3","version":7,"kind":"scale","prompt":"Resize the wire stripper to match its real size.","target":{"name":"Wire stripper","dimension":"reference overall length","shape":"photo:wire-stripper"},"reference":{"name":"AKG C214 microphone","dimension":"microphone height","shape":"photo:akg-microphone","measure":"16 cm · microphone height"},"bounds":[0.02,50],"answer":1.0625,"explanation":"Wire stripper: 0.17 m (reference overall length). AKG C214 microphone: 0.16 m (microphone height). Ratio: 1.06×.\nA 17 cm hand-tool reference. The photograph supplies the outline, not a scale calibration.\nC214 microphone height: 160 mm, without a stand.","sources":["https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://www.akg.com/Microphones/Condenser%20Microphones/C214.html","https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://commons.wikimedia.org/wiki/File:AKG_C214_Condenser_microphone.png"]},{"id":"photo-size-v7-4","version":7,"kind":"scale","prompt":"Resize the sunglasses to match its real size.","target":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses"},"reference":{"name":"Original Nintendo DS","dimension":"console width","shape":"photo:nintendo-ds","measure":"14.87 cm · console width"},"bounds":[0.02,50],"answer":0.94149294,"explanation":"Sunglasses: 0.14 m (reference front width). Original Nintendo DS: 0.1487 m (console width). Ratio: 0.94×.\nA 14 cm front-width reference, not the length of the folding arms.\nOriginal DS width: 148.7 mm.","sources":["https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://en.wikipedia.org/wiki/Nintendo_DS","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png"]},{"id":"photo-size-v7-5","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"Kick scooter","dimension":"reference handlebar height","shape":"photo:skateboard","measure":"1 m · reference handlebar height"},"bounds":[0.02,50],"answer":0.131,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). Kick scooter: 1 m (reference handlebar height). Ratio: 0.13×.\nT7M overall length: 131 mm.\nA one-metre handlebar-height reference. Adjustable scooters can be set lower.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://www.stigasports.com/","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:Stiga_Route_200_S.png"]}]'::jsonb WHERE game='how-much-ish' AND slot=1;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"photo-size-v7-6","version":7,"kind":"scale","prompt":"Resize the game boy micro to match its real size.","target":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro"},"reference":{"name":"Billiard chalk cube","dimension":"reference cube width","shape":"photo:chalk","measure":"2.5 cm · reference cube width"},"bounds":[0.02,50],"answer":4.04,"explanation":"Game Boy Micro: 0.101 m (console width). Billiard chalk cube: 0.025 m (reference cube width). Ratio: 4.04×.\nThe Micro is 101 mm wide.\nA 2.5 cm chalk-cube reference.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Micro","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png"]},{"id":"photo-size-v7-7","version":7,"kind":"scale","prompt":"Resize the f tuba to match its real size.","target":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba"},"reference":{"name":"Concrete mixer truck","dimension":"reference overall length","shape":"photo:cement-truck","measure":"9 m · reference overall length"},"bounds":[0.02,50],"answer":0.1,"explanation":"F tuba: 0.9 m (reference standing height). Concrete mixer truck: 9 m (reference overall length). Ratio: 0.10×.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.\nA nine-metre mixer-truck reference. Chassis and mixer configuration affect exact length.","sources":["https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png"]},{"id":"photo-size-v7-8","version":7,"kind":"scale","prompt":"Resize the olympus e-pl1 to match its real size.","target":{"name":"Olympus E-PL1","dimension":"camera body width","shape":"photo:olympus"},"reference":{"name":"Full-size violin","dimension":"typical overall length","shape":"photo:violin","measure":"59 cm · typical overall length"},"bounds":[0.02,50],"answer":0.19423729,"explanation":"Olympus E-PL1: 0.1146 m (camera body width). Full-size violin: 0.59 m (typical overall length). Ratio: 0.19×.\nE-PL1 body width: 114.6 mm.\nA full-size violin is about 59 cm overall. The bow is excluded.","sources":["https://en.wikipedia.org/wiki/Olympus_PEN_E-PL1","https://www.yamaha.com/en/musical_instrument_guide/violin/structure/","https://commons.wikimedia.org/wiki/File:Olympus_E-PL1.png","https://commons.wikimedia.org/wiki/File:Violin_VL100_(cropped).png"]},{"id":"photo-size-v7-9","version":7,"kind":"scale","prompt":"Resize the broccoli head to match its real size.","target":{"name":"Broccoli head","dimension":"reference overall height","shape":"photo:broccoli"},"reference":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini","measure":"19.7 cm · enclosure width"},"bounds":[0.02,50],"answer":1.01522843,"explanation":"Broccoli head: 0.2 m (reference overall height). 2010 Mac mini: 0.197 m (enclosure width). Ratio: 1.02×.\nA 20 cm broccoli reference including its stalk.\nThis Mac mini generation has a 19.7 cm square footprint.","sources":["https://commons.wikimedia.org/wiki/File:Broccoli.png","https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png"]},{"id":"photo-size-v7-10","version":7,"kind":"scale","prompt":"Resize the bicycle chain tool to match its real size.","target":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool"},"reference":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard","measure":"43 cm · keyboard-computer width"},"bounds":[0.02,50],"answer":0.18604651,"explanation":"Bicycle chain tool: 0.08 m (reference overall height). Commodore 128: 0.43 m (keyboard-computer width). Ratio: 0.19×.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.\nA 43 cm wide keyboard-computer reference.","sources":["https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png"]}]'::jsonb WHERE game='how-much-ish' AND slot=2;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"photo-size-v7-11","version":7,"kind":"scale","prompt":"Resize the open umbrella to match its real size.","target":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella"},"reference":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce","measure":"5.79 m · reference coachwork length"},"bounds":[0.02,50],"answer":0.17271157,"explanation":"Open umbrella: 1 m (reference canopy width). Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Ratio: 0.17×.\nA one-metre canopy-width reference. Umbrella models vary.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.","sources":["https://commons.wikimedia.org/wiki/File:Umbrella.png","https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png"]},{"id":"photo-size-v7-12","version":7,"kind":"scale","prompt":"Resize the atari portfolio to match its real size.","target":{"name":"Atari Portfolio","dimension":"computer width","shape":"photo:calculator"},"reference":{"name":"Tennis ball","dimension":"reference ball diameter","shape":"photo:tennis-ball","measure":"6.7 cm · reference ball diameter"},"bounds":[0.02,50],"answer":2.98507463,"explanation":"Atari Portfolio: 0.2 m (computer width). Tennis ball: 0.067 m (reference ball diameter). Ratio: 2.99×.\nThe pocket computer is about 20 cm wide.\nA 6.7 cm diameter reference, within the standard ball-size range.","sources":["https://en.wikipedia.org/wiki/Atari_Portfolio","https://www.itftennis.com/en/about-us/tennis-tech/approved-balls/","https://commons.wikimedia.org/wiki/File:Atari-Portfolio-Computer.png","https://commons.wikimedia.org/wiki/File:Tennisball2.png"]},{"id":"photo-size-v7-13","version":7,"kind":"scale","prompt":"Resize the land tortoise to match its real size.","target":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise"},"reference":{"name":"Sega Nomad","dimension":"console width","shape":"photo:sega-nomad","measure":"18.5 cm · console width"},"bounds":[0.02,50],"answer":1.62162162,"explanation":"Land tortoise: 0.3 m (reference overall length). Sega Nomad: 0.185 m (console width). Ratio: 1.62×.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.\nThe Nomad is approximately 18.5 cm wide.","sources":["https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://en.wikipedia.org/wiki/Genesis_Nomad","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Sega-Nomad-Front_(rotated).png"]},{"id":"photo-size-v7-14","version":7,"kind":"scale","prompt":"Resize the soprano recorder to match its real size.","target":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder"},"reference":{"name":"Drywall screw","dimension":"reference screw length","shape":"photo:screw","measure":"3.5 cm · reference screw length"},"bounds":[0.02,50],"answer":9.14285714,"explanation":"Soprano recorder: 0.32 m (reference length). Drywall screw: 0.035 m (reference screw length). Ratio: 9.14×.\nA 32 cm soprano recorder reference; recorders come in many sizes.\nA 35 mm drywall-screw reference; this is one selected size, not a universal screw length.","sources":["https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png","https://commons.wikimedia.org/wiki/File:Drywall_screw.png"]},{"id":"photo-size-v7-15","version":7,"kind":"scale","prompt":"Resize the dreamcast vmu to match its real size.","target":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu"},"reference":{"name":"Climbing hammer","dimension":"reference overall length","shape":"photo:climbing-hammer","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":0.26666667,"explanation":"Dreamcast VMU: 0.08 m (unit height). Climbing hammer: 0.3 m (reference overall length). Ratio: 0.27×.\nThe Visual Memory Unit is about 80 mm high.\nA 30 cm hand-tool reference.","sources":["https://en.wikipedia.org/wiki/VMU","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png"]}]'::jsonb WHERE game='how-much-ish' AND slot=3;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"photo-size-v7-16","version":7,"kind":"scale","prompt":"Resize the nes controller to match its real size.","target":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller"},"reference":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly","measure":"6.5 cm · reference wingspan"},"bounds":[0.02,50],"answer":1.89230769,"explanation":"NES controller: 0.123 m (body width). Peacock butterfly: 0.065 m (reference wingspan). Ratio: 1.89×.\nA 123 mm controller body reference; the cable is excluded.\nA 65 mm wingspan reference with the wings spread.","sources":["https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://butterfly-conservation.org/butterflies/peacock","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png"]},{"id":"photo-size-v7-17","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"Apple","dimension":"reference fruit width","shape":"photo:apple","measure":"8 cm · reference fruit width"},"bounds":[0.02,50],"answer":0.5,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). Apple: 0.08 m (reference fruit width). Ratio: 0.50×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nAn 8 cm wide reference apple; real apples vary by cultivar and growing conditions.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png"]},{"id":"photo-size-v7-18","version":7,"kind":"scale","prompt":"Resize the game boy advance to match its real size.","target":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba"},"reference":{"name":"Size-7 basketball","dimension":"nominal diameter","shape":"photo:basketball","measure":"23.9 cm · nominal diameter"},"bounds":[0.02,50],"answer":0.60460251,"explanation":"Game Boy Advance: 0.1445 m (console width). Size-7 basketball: 0.239 m (nominal diameter). Ratio: 0.60×.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.\nA nominal diameter of 23.9 cm, corresponding to about 75 cm circumference.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance","https://www.fiba.basketball/en/official-basketball-rules","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png","https://commons.wikimedia.org/wiki/File:Isolated_basketball.png"]},{"id":"photo-size-v7-19","version":7,"kind":"scale","prompt":"Resize the xd-picture card to match its real size.","target":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card"},"reference":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor","measure":"10 cm · reference overall length"},"bounds":[0.02,50],"answer":0.25,"explanation":"xD-Picture Card: 0.025 m (card width). Disposable razor: 0.1 m (reference overall length). Ratio: 0.25×.\nThe memory card is 25 mm wide and 20 mm high.\nA 10 cm razor reference, measured end to end.","sources":["https://en.wikipedia.org/wiki/XD-Picture_Card","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png","https://commons.wikimedia.org/wiki/File:Razor.png"]},{"id":"photo-size-v7-20","version":7,"kind":"scale","prompt":"Resize the full-size electric guitar to match its real size.","target":{"name":"Full-size electric guitar","dimension":"reference overall length","shape":"photo:guitar"},"reference":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90","measure":"13.2 cm · camera body width"},"bounds":[0.02,50],"answer":7.57575758,"explanation":"Full-size electric guitar: 1 m (reference overall length). Nikon D90: 0.132 m (camera body width). Ratio: 7.58×.\nA one-metre reference guitar. Overall length varies by model; this is not its string scale length.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.","sources":["https://www.fender.com/articles/instruments/what-is-scale-length","https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Guitar_3.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png"]}]'::jsonb WHERE game='how-much-ish' AND slot=4;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"photo-size-v7-21","version":7,"kind":"scale","prompt":"Resize the media remote control to match its real size.","target":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote"},"reference":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra","measure":"2.4 m · reference head-and-body length"},"bounds":[0.02,50],"answer":0.06041667,"explanation":"Media remote control: 0.145 m (reference overall length). Plains zebra: 2.4 m (reference head-and-body length). Ratio: 0.06×.\nA 14.5 cm reference remote, measured end to end.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.","sources":["https://www.playstation.com/en-us/accessories/media-remote/","https://animals.sandiegozoo.org/animals/zebra","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png"]},{"id":"photo-size-v7-22","version":7,"kind":"scale","prompt":"Resize the dualshock 2 controller to match its real size.","target":{"name":"DualShock 2 controller","dimension":"reference controller width","shape":"photo:controller"},"reference":{"name":"Coffee bean","dimension":"reference long-axis length","shape":"photo:coffee-bean","measure":"1 cm · reference long-axis length"},"bounds":[0.02,50],"answer":15.7,"explanation":"DualShock 2 controller: 0.157 m (reference controller width). Coffee bean: 0.01 m (reference long-axis length). Ratio: 15.70×.\nA 15.7 cm controller-body width reference, excluding the cable.\nA 10 mm roasted-coffee-bean reference.","sources":["https://en.wikipedia.org/wiki/DualShock","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:PlayStation2-DualShock2.png","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png"]},{"id":"photo-size-v7-23","version":7,"kind":"scale","prompt":"Resize the adult male giraffe to match its real size.","target":{"name":"Adult male giraffe","dimension":"upper adult height","shape":"photo:giraffe"},"reference":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute","measure":"67 cm · typical assembled length"},"bounds":[0.02,50],"answer":8.20895522,"explanation":"Adult male giraffe: 5.5 m (upper adult height). Concert flute: 0.67 m (typical assembled length). Ratio: 8.21×.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.\nA reference concert flute about 67 cm long; model and footjoint affect length.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png"]},{"id":"photo-size-v7-24","version":7,"kind":"scale","prompt":"Resize the game boy advance sp to match its real size.","target":{"name":"Game Boy Advance SP","dimension":"console width","shape":"photo:gba-sp"},"reference":{"name":"Small scissors","dimension":"reference end-to-end length","shape":"photo:scissors","measure":"14 cm · reference end-to-end length"},"bounds":[0.02,50],"answer":0.60428571,"explanation":"Game Boy Advance SP: 0.0846 m (console width). Small scissors: 0.14 m (reference end-to-end length). Ratio: 0.60×.\nThe SP is 84.6 mm wide, whether open or closed.\nA 14 cm household-scissors reference, measured from handle end to blade tip.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance_SP","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Advance-SP-Mk2.png","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png"]},{"id":"photo-size-v7-25","version":7,"kind":"scale","prompt":"Resize the three-cup moka pot to match its real size.","target":{"name":"Three-cup moka pot","dimension":"reference height","shape":"photo:coffee-pot"},"reference":{"name":"Chameleon","dimension":"reference overall length","shape":"photo:chameleon","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":0.53333333,"explanation":"Three-cup moka pot: 0.16 m (reference height). Chameleon: 0.3 m (reference overall length). Ratio: 0.53×.\nA roughly 16 cm three-cup reference. Moka pots are sold in many capacities.\nA 30 cm reference specimen including the tail. Chameleon species vary widely.","sources":["https://www.bialetti.com/ee_en/moka-express.html","https://animals.sandiegozoo.org/animals/chameleon","https://commons.wikimedia.org/wiki/File:Moka_Express_sideview.png","https://commons.wikimedia.org/wiki/File:ChameleonCutOut.png"]}]'::jsonb WHERE game='how-much-ish' AND slot=5;
