CREATE FUNCTION ledger_private.photo_size_catalog_version() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT 1;$$;
CREATE OR REPLACE FUNCTION public.utilities_trivia_capabilities() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('version',6,'games',7,'groups',true,'size_objects',59,'online_sync',true,'online_seed',1,'archive',true,'grid_puzzles',true,'photo_silhouettes',true);$$;
