INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',0,7,'[{"id":"photo-size-v7-101","version":7,"kind":"scale","prompt":"Resize the drywall screw to match its real size.","target":{"name":"Drywall screw","dimension":"reference screw length","shape":"photo:screw"},"reference":{"name":"Nintendo Switch","dimension":"width with Joy-Con","shape":"photo:switch","measure":"23.9 cm · width with Joy-Con"},"bounds":[0.02,50],"answer":0.14644351,"explanation":"Drywall screw: 0.035 m (reference screw length). Nintendo Switch: 0.239 m (width with Joy-Con). Ratio: 0.15×.\nA 35 mm drywall-screw reference; this is one selected size, not a universal screw length.\nOriginal Nintendo Switch: 239 mm wide with Joy-Con attached.","sources":["https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://www.nintendo.com/us/gaming-systems/switch/tech-specs/","https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://commons.wikimedia.org/wiki/File:Nintendo-Switch-wJoyCons-BlRd-Standing-FL.png"]},{"id":"photo-size-v7-102","version":7,"kind":"scale","prompt":"Resize the commodore 128 to match its real size.","target":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard"},"reference":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller","measure":"5 m · reference overall length"},"bounds":[0.02,50],"answer":0.086,"explanation":"Commodore 128: 0.43 m (keyboard-computer width). Road roller: 5 m (reference overall length). Ratio: 0.09×.\nA 43 cm wide keyboard-computer reference.\nA five-metre road-roller reference; construction machines come in many sizes.","sources":["https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png","https://commons.wikimedia.org/wiki/File:Road_roller.png"]},{"id":"photo-size-v7-103","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"Original Nintendo DS","dimension":"console width","shape":"photo:nintendo-ds","measure":"14.87 cm · console width"},"bounds":[0.02,50],"answer":0.26899798,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). Original Nintendo DS: 0.1487 m (console width). Ratio: 0.27×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nOriginal DS width: 148.7 mm.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://en.wikipedia.org/wiki/Nintendo_DS","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png"]},{"id":"photo-size-v7-104","version":7,"kind":"scale","prompt":"Resize the xd-picture card to match its real size.","target":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card"},"reference":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder","measure":"32 cm · reference length"},"bounds":[0.02,50],"answer":0.078125,"explanation":"xD-Picture Card: 0.025 m (card width). Soprano recorder: 0.32 m (reference length). Ratio: 0.08×.\nThe memory card is 25 mm wide and 20 mm high.\nA 32 cm soprano recorder reference; recorders come in many sizes.","sources":["https://en.wikipedia.org/wiki/XD-Picture_Card","https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png"]},{"id":"photo-size-v7-105","version":7,"kind":"scale","prompt":"Resize the peacock butterfly to match its real size.","target":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly"},"reference":{"name":"Game Boy Color","dimension":"console height","shape":"photo:gameboy-color","measure":"13.35 cm · console height"},"bounds":[0.02,50],"answer":0.48689139,"explanation":"Peacock butterfly: 0.065 m (reference wingspan). Game Boy Color: 0.1335 m (console height). Ratio: 0.49×.\nA 65 mm wingspan reference with the wings spread.\nThe Game Boy Color is 133.5 mm high.","sources":["https://butterfly-conservation.org/butterflies/peacock","https://en.wikipedia.org/wiki/Game_Boy_Color","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',1,7,'[{"id":"photo-size-v7-106","version":7,"kind":"scale","prompt":"Resize the seven-spot ladybird to match its real size.","target":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird"},"reference":{"name":"Tennis ball","dimension":"reference ball diameter","shape":"photo:tennis-ball","measure":"6.7 cm · reference ball diameter"},"bounds":[0.02,50],"answer":0.10447761,"explanation":"Seven-spot ladybird: 0.007 m (reference body length). Tennis ball: 0.067 m (reference ball diameter). Ratio: 0.10×.\nA 7 mm adult reference, excluding legs and antennae.\nA 6.7 cm diameter reference, within the standard ball-size range.","sources":["https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://www.itftennis.com/en/about-us/tennis-tech/approved-balls/","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png","https://commons.wikimedia.org/wiki/File:Tennisball2.png"]},{"id":"photo-size-v7-107","version":7,"kind":"scale","prompt":"Resize the bicycle chain tool to match its real size.","target":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool"},"reference":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor","measure":"10 cm · reference overall length"},"bounds":[0.02,50],"answer":0.8,"explanation":"Bicycle chain tool: 0.08 m (reference overall height). Disposable razor: 0.1 m (reference overall length). Ratio: 0.80×.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.\nA 10 cm razor reference, measured end to end.","sources":["https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Razor.png"]},{"id":"photo-size-v7-108","version":7,"kind":"scale","prompt":"Resize the plains zebra to match its real size.","target":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra"},"reference":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller","measure":"12.3 cm · body width"},"bounds":[0.02,50],"answer":19.51219512,"explanation":"Plains zebra: 2.4 m (reference head-and-body length). NES controller: 0.123 m (body width). Ratio: 19.51×.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.\nA 123 mm controller body reference; the cable is excluded.","sources":["https://animals.sandiegozoo.org/animals/zebra","https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png"]},{"id":"photo-size-v7-109","version":7,"kind":"scale","prompt":"Resize the media remote control to match its real size.","target":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote"},"reference":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute","measure":"67 cm · typical assembled length"},"bounds":[0.02,50],"answer":0.21641791,"explanation":"Media remote control: 0.145 m (reference overall length). Concert flute: 0.67 m (typical assembled length). Ratio: 0.22×.\nA 14.5 cm reference remote, measured end to end.\nA reference concert flute about 67 cm long; model and footjoint affect length.","sources":["https://www.playstation.com/en-us/accessories/media-remote/","https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png"]},{"id":"photo-size-v7-110","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"DualShock 2 controller","dimension":"reference controller width","shape":"photo:controller","measure":"15.7 cm · reference controller width"},"bounds":[0.02,50],"answer":0.8343949,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). DualShock 2 controller: 0.157 m (reference controller width). Ratio: 0.83×.\nT7M overall length: 131 mm.\nA 15.7 cm controller-body width reference, excluding the cable.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://en.wikipedia.org/wiki/DualShock","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:PlayStation2-DualShock2.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',2,7,'[{"id":"photo-size-v7-111","version":7,"kind":"scale","prompt":"Resize the coffee bean to match its real size.","target":{"name":"Coffee bean","dimension":"reference long-axis length","shape":"photo:coffee-bean"},"reference":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90","measure":"13.2 cm · camera body width"},"bounds":[0.02,50],"answer":0.07575758,"explanation":"Coffee bean: 0.01 m (reference long-axis length). Nikon D90: 0.132 m (camera body width). Ratio: 0.08×.\nA 10 mm roasted-coffee-bean reference.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.","sources":["https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png"]},{"id":"photo-size-v7-112","version":7,"kind":"scale","prompt":"Resize the adult male giraffe to match its real size.","target":{"name":"Adult male giraffe","dimension":"upper adult height","shape":"photo:giraffe"},"reference":{"name":"Concrete mixer truck","dimension":"reference overall length","shape":"photo:cement-truck","measure":"9 m · reference overall length"},"bounds":[0.02,50],"answer":0.61111111,"explanation":"Adult male giraffe: 5.5 m (upper adult height). Concrete mixer truck: 9 m (reference overall length). Ratio: 0.61×.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.\nA nine-metre mixer-truck reference. Chassis and mixer configuration affect exact length.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png"]},{"id":"photo-size-v7-113","version":7,"kind":"scale","prompt":"Resize the iphone 3g to match its real size.","target":{"name":"iPhone 3G","dimension":"phone height","shape":"photo:iphone3g"},"reference":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella","measure":"1 m · reference canopy width"},"bounds":[0.02,50],"answer":0.1155,"explanation":"iPhone 3G: 0.1155 m (phone height). Open umbrella: 1 m (reference canopy width). Ratio: 0.12×.\niPhone 3G height: 115.5 mm.\nA one-metre canopy-width reference. Umbrella models vary.","sources":["https://devimages.apple.com/programs/ipod/dimensions/iPhone-3G-dimensions.pdf","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:IPhone_3G.png","https://commons.wikimedia.org/wiki/File:Umbrella.png"]},{"id":"photo-size-v7-114","version":7,"kind":"scale","prompt":"Resize the game boy micro to match its real size.","target":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro"},"reference":{"name":"Kick scooter","dimension":"reference handlebar height","shape":"photo:skateboard","measure":"1 m · reference handlebar height"},"bounds":[0.02,50],"answer":0.101,"explanation":"Game Boy Micro: 0.101 m (console width). Kick scooter: 1 m (reference handlebar height). Ratio: 0.10×.\nThe Micro is 101 mm wide.\nA one-metre handlebar-height reference. Adjustable scooters can be set lower.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Micro","https://www.stigasports.com/","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png","https://commons.wikimedia.org/wiki/File:Stiga_Route_200_S.png"]},{"id":"photo-size-v7-115","version":7,"kind":"scale","prompt":"Resize the akg c214 microphone to match its real size.","target":{"name":"AKG C214 microphone","dimension":"microphone height","shape":"photo:akg-microphone"},"reference":{"name":"Billiard chalk cube","dimension":"reference cube width","shape":"photo:chalk","measure":"2.5 cm · reference cube width"},"bounds":[0.02,50],"answer":6.4,"explanation":"AKG C214 microphone: 0.16 m (microphone height). Billiard chalk cube: 0.025 m (reference cube width). Ratio: 6.40×.\nC214 microphone height: 160 mm, without a stand.\nA 2.5 cm chalk-cube reference.","sources":["https://www.akg.com/Microphones/Condenser%20Microphones/C214.html","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:AKG_C214_Condenser_microphone.png","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',3,7,'[{"id":"photo-size-v7-116","version":7,"kind":"scale","prompt":"Resize the blackberry q10 to match its real size.","target":{"name":"BlackBerry Q10","dimension":"phone height","shape":"photo:blackberry"},"reference":{"name":"Broccoli head","dimension":"reference overall height","shape":"photo:broccoli","measure":"20 cm · reference overall height"},"bounds":[0.02,50],"answer":0.598,"explanation":"BlackBerry Q10: 0.1196 m (phone height). Broccoli head: 0.2 m (reference overall height). Ratio: 0.60×.\nBlackBerry Q10 height: 119.6 mm.\nA 20 cm broccoli reference including its stalk.","sources":["https://en.wikipedia.org/wiki/BlackBerry_Q10","https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:Blackberry-Q10-transparent.png","https://commons.wikimedia.org/wiki/File:Broccoli.png"]},{"id":"photo-size-v7-117","version":7,"kind":"scale","prompt":"Resize the 2010 mac mini to match its real size.","target":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini"},"reference":{"name":"Avocado","dimension":"reference fruit length","shape":"photo:avocado","measure":"14 cm · reference fruit length"},"bounds":[0.02,50],"answer":1.40714286,"explanation":"2010 Mac mini: 0.197 m (enclosure width). Avocado: 0.14 m (reference fruit length). Ratio: 1.41×.\nThis Mac mini generation has a 19.7 cm square footprint.\nA 14 cm reference avocado. Fruit sizes vary considerably.","sources":["https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png","https://commons.wikimedia.org/wiki/File:Avocado.png"]},{"id":"photo-size-v7-118","version":7,"kind":"scale","prompt":"Resize the peacock butterfly to match its real size.","target":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly"},"reference":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera","measure":"10.96 cm · camera body width"},"bounds":[0.02,50],"answer":0.59306569,"explanation":"Peacock butterfly: 0.065 m (reference wingspan). Sony a5000: 0.1096 m (camera body width). Ratio: 0.59×.\nA 65 mm wingspan reference with the wings spread.\nSony a5000 body width: 109.6 mm.","sources":["https://butterfly-conservation.org/butterflies/peacock","https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png"]},{"id":"photo-size-v7-119","version":7,"kind":"scale","prompt":"Resize the size-7 basketball to match its real size.","target":{"name":"Size-7 basketball","dimension":"nominal diameter","shape":"photo:basketball"},"reference":{"name":"Atari Portfolio","dimension":"computer width","shape":"photo:calculator","measure":"20 cm · computer width"},"bounds":[0.02,50],"answer":1.195,"explanation":"Size-7 basketball: 0.239 m (nominal diameter). Atari Portfolio: 0.2 m (computer width). Ratio: 1.19×.\nA nominal diameter of 23.9 cm, corresponding to about 75 cm circumference.\nThe pocket computer is about 20 cm wide.","sources":["https://www.fiba.basketball/en/official-basketball-rules","https://en.wikipedia.org/wiki/Atari_Portfolio","https://commons.wikimedia.org/wiki/File:Isolated_basketball.png","https://commons.wikimedia.org/wiki/File:Atari-Portfolio-Computer.png"]},{"id":"photo-size-v7-120","version":7,"kind":"scale","prompt":"Resize the f tuba to match its real size.","target":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba"},"reference":{"name":"Honda S2000","dimension":"vehicle length","shape":"photo:honda-s2000","measure":"4.135 m · vehicle length"},"bounds":[0.02,50],"answer":0.21765417,"explanation":"F tuba: 0.9 m (reference standing height). Honda S2000: 4.135 m (vehicle length). Ratio: 0.22×.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.\n2005 S2000 overall length: 4.135 m.","sources":["https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://en.wikipedia.org/wiki/Honda_S2000","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png","https://commons.wikimedia.org/wiki/File:HondaS2000-004.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',4,7,'[{"id":"photo-size-v7-121","version":7,"kind":"scale","prompt":"Resize the european badger to match its real size.","target":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger"},"reference":{"name":"City transit bus","dimension":"40-foot bus length","shape":"photo:bus","measure":"12.2 m · 40-foot bus length"},"bounds":[0.02,50],"answer":0.06147541,"explanation":"European badger: 0.75 m (reference head-and-body length). City transit bus: 12.2 m (40-foot bus length). Ratio: 0.06×.\nA 75 cm adult reference, excluding the tail. Adults vary in size.\nA nominal 40-foot (12.2 m) transit-bus reference; bumpers and model year affect exact length.","sources":["https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://www.gillig.com/low-floor","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png","https://commons.wikimedia.org/wiki/File:Transparent_Santa_Cruz_Metro_bus_0222.png"]},{"id":"photo-size-v7-122","version":7,"kind":"scale","prompt":"Resize the game boy advance to match its real size.","target":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba"},"reference":{"name":"Full-size violin","dimension":"typical overall length","shape":"photo:violin","measure":"59 cm · typical overall length"},"bounds":[0.02,50],"answer":0.24491525,"explanation":"Game Boy Advance: 0.1445 m (console width). Full-size violin: 0.59 m (typical overall length). Ratio: 0.24×.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.\nA full-size violin is about 59 cm overall. The bow is excluded.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance","https://www.yamaha.com/en/musical_instrument_guide/violin/structure/","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png","https://commons.wikimedia.org/wiki/File:Violin_VL100_(cropped).png"]},{"id":"photo-size-v7-123","version":7,"kind":"scale","prompt":"Resize the rolls-royce phantom iii to match its real size.","target":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce"},"reference":{"name":"Climbing hammer","dimension":"reference overall length","shape":"photo:climbing-hammer","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":19.3,"explanation":"Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Climbing hammer: 0.3 m (reference overall length). Ratio: 19.30×.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.\nA 30 cm hand-tool reference.","sources":["https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png"]},{"id":"photo-size-v7-124","version":7,"kind":"scale","prompt":"Resize the computer mouse to match its real size.","target":{"name":"Computer mouse","dimension":"reference body length","shape":"photo:sega-mouse"},"reference":{"name":"Wire stripper","dimension":"reference overall length","shape":"photo:wire-stripper","measure":"17 cm · reference overall length"},"bounds":[0.02,50],"answer":0.64705882,"explanation":"Computer mouse: 0.11 m (reference body length). Wire stripper: 0.17 m (reference overall length). Ratio: 0.65×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 17 cm hand-tool reference. The photograph supplies the outline, not a scale calibration.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Wire_stripper.png"]},{"id":"photo-size-v7-125","version":7,"kind":"scale","prompt":"Resize the sunglasses to match its real size.","target":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses"},"reference":{"name":"Game Boy Advance SP","dimension":"console width","shape":"photo:gba-sp","measure":"8.46 cm · console width"},"bounds":[0.02,50],"answer":1.65484634,"explanation":"Sunglasses: 0.14 m (reference front width). Game Boy Advance SP: 0.0846 m (console width). Ratio: 1.65×.\nA 14 cm front-width reference, not the length of the folding arms.\nThe SP is 84.6 mm wide, whether open or closed.","sources":["https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://en.wikipedia.org/wiki/Game_Boy_Advance_SP","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Advance-SP-Mk2.png"]}]'::jsonb);
