sion":"overall length","shape":"photo:flashlight","measure":"13.1 cm · overall length"},"bounds":[0.02,50],"answer":1.29770992,"explanation":"Bicycle master-link pliers: 0.17 m (reference overall length). Ledlenser T7M flashlight: 0.131 m (overall length). Ratio: 1.30×.\nA 17 cm pliers reference; tool models differ.\nT7M overall length: 131 mm.","sources":["https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://www.ledlenser.my/product/flashlights/t7m/","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',12,7,'[{"id":"photo-size-v7-161","version":7,"kind":"scale","prompt":"Resize the road roller to match its real size.","target":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller"},"reference":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard","measure":"43 cm · keyboard-computer width"},"bounds":[0.02,50],"answer":11.62790698,"explanation":"Road roller: 5 m (reference overall length). Commodore 128: 0.43 m (keyboard-computer width). Ratio: 11.63×.\nA five-metre road-roller reference; construction machines come in many sizes.\nA 43 cm wide keyboard-computer reference.","sources":["https://commons.wikimedia.org/wiki/File:Road_roller.png","https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png"]},{"id":"photo-size-v7-162","version":7,"kind":"scale","prompt":"Resize the chameleon to match its real size.","target":{"name":"Chameleon","dimension":"reference overall length","shape":"photo:chameleon"},"reference":{"name":"BlackBerry Q10","dimension":"phone height","shape":"photo:blackberry","measure":"11.96 cm · phone height"},"bounds":[0.02,50],"answer":2.5083612,"explanation":"Chameleon: 0.3 m (reference overall length). BlackBerry Q10: 0.1196 m (phone height). Ratio: 2.51×.\nA 30 cm reference specimen including the tail. Chameleon species vary widely.\nBlackBerry Q10 height: 119.6 mm.","sources":["https://animals.sandiegozoo.org/animals/chameleon","https://en.wikipedia.org/wiki/BlackBerry_Q10","https://commons.wikimedia.org/wiki/File:ChameleonCutOut.png","https://commons.wikimedia.org/wiki/File:Blackberry-Q10-transparent.png"]},{"id":"photo-size-v7-163","version":7,"kind":"scale","prompt":"Resize the avocado to match its real size.","target":{"name":"Avocado","dimension":"reference fruit length","shape":"photo:avocado"},"reference":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro","measure":"10.1 cm · console width"},"bounds":[0.02,50],"answer":1.38613861,"explanation":"Avocado: 0.14 m (reference fruit length). Game Boy Micro: 0.101 m (console width). Ratio: 1.39×.\nA 14 cm reference avocado. Fruit sizes vary considerably.\nThe Micro is 101 mm wide.","sources":["https://commons.wikimedia.org/wiki/File:Avocado.png","https://en.wikipedia.org/wiki/Game_Boy_Micro","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png"]},{"id":"photo-size-v7-164","version":7,"kind":"scale","prompt":"Resize the dreamcast vmu to match its real size.","target":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu"},"reference":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor","measure":"10 cm · reference overall length"},"bounds":[0.02,50],"answer":0.8,"explanation":"Dreamcast VMU: 0.08 m (unit height). Disposable razor: 0.1 m (reference overall length). Ratio: 0.80×.\nThe Visual Memory Unit is about 80 mm high.\nA 10 cm razor reference, measured end to end.","sources":["https://en.wikipedia.org/wiki/VMU","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png","https://commons.wikimedia.org/wiki/File:Razor.png"]},{"id":"photo-size-v7-165","version":7,"kind":"scale","prompt":"Resize the plains zebra to match its real size.","target":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra"},"reference":{"name":"Small scissors","dimension":"reference end-to-end length","shape":"photo:scissors","measure":"14 cm · reference end-to-end length"},"bounds":[0.02,50],"answer":17.14285714,"explanation":"Plains zebra: 2.4 m (reference head-and-body length). Small scissors: 0.14 m (reference end-to-end length). Ratio: 17.14×.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.\nA 14 cm household-scissors reference, measured from handle end to blade tip.","sources":["https://animals.sandiegozoo.org/animals/zebra","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',13,7,'[{"id":"photo-size-v7-166","version":7,"kind":"scale","prompt":"Resize the sony a5000 to match its real size.","target":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera"},"reference":{"name":"Drywall screw","dimension":"reference screw length","shape":"photo:screw","measure":"3.5 cm · reference screw length"},"bounds":[0.02,50],"answer":3.13142857,"explanation":"Sony a5000: 0.1096 m (camera body width). Drywall screw: 0.035 m (reference screw length). Ratio: 3.13×.\nSony a5000 body width: 109.6 mm.\nA 35 mm drywall-screw reference; this is one selected size, not a universal screw length.","sources":["https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png","https://commons.wikimedia.org/wiki/File:Drywall_screw.png"]},{"id":"photo-size-v7-167","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"AKG C214 microphone","dimension":"microphone height","shape":"photo:akg-microphone","measure":"16 cm · microphone height"},"bounds":[0.02,50],"answer":0.25,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). AKG C214 microphone: 0.16 m (microphone height). Ratio: 0.25×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nC214 microphone height: 160 mm, without a stand.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://www.akg.com/Microphones/Condenser%20Microphones/C214.html","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:AKG_C214_Condenser_microphone.png"]},{"id":"photo-size-v7-168","version":7,"kind":"scale","prompt":"Resize th