INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',16,7,'[{"id":"photo-size-v7-181","version":7,"kind":"scale","prompt":"Resize the game boy advance to match its real size.","target":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba"},"reference":{"name":"Drywall screw","dimension":"reference screw length","shape":"photo:screw","measure":"3.5 cm · reference screw length"},"bounds":[0.02,50],"answer":4.12857143,"explanation":"Game Boy Advance: 0.1445 m (console width). Drywall screw: 0.035 m (reference screw length). Ratio: 4.13×.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.\nA 35 mm drywall-screw reference; this is one selected size, not a universal screw length.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance","https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png","https://commons.wikimedia.org/wiki/File:Drywall_screw.png"]},{"id":"photo-size-v7-182","version":7,"kind":"scale","prompt":"Resize the concrete mixer truck to match its real size.","target":{"name":"Concrete mixer truck","dimension":"reference overall length","shape":"photo:cement-truck"},"reference":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba","measure":"90 cm · reference standing height"},"bounds":[0.02,50],"answer":10,"explanation":"Concrete mixer truck: 9 m (reference overall length). F tuba: 0.9 m (reference standing height). Ratio: 10.00×.\nA nine-metre mixer-truck reference. Chassis and mixer configuration affect exact length.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.","sources":["https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png","https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png"]},{"id":"photo-size-v7-183","version":7,"kind":"scale","prompt":"Resize the rolls-royce phantom iii to match its real size.","target":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce"},"reference":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":19.3,"explanation":"Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Land tortoise: 0.3 m (reference overall length). Ratio: 19.30×.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.","sources":["https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png"]},{"id":"photo-size-v7-184","version":7,"kind":"scale","prompt":"Resize the adult male giraffe to match its real size.","target":{"name":"Adult male giraffe","dimension":"upper adult height","shape":"photo:giraffe"},"reference":{"name":"City transit bus","dimension":"40-foot bus length","shape":"photo:bus","measure":"12.2 m · 40-foot bus length"},"bounds":[0.02,50],"answer":0.45081967,"explanation":"Adult male giraffe: 5.5 m (upper adult height). City transit bus: 12.2 m (40-foot bus length). Ratio: 0.45×.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.\nA nominal 40-foot (12.2 m) transit-bus reference; bumpers and model year affect exact length.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.gillig.com/low-floor","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png","https://commons.wikimedia.org/wiki/File:Transparent_Santa_Cruz_Metro_bus_0222.png"]},{"id":"photo-size-v7-185","version":7,"kind":"scale","prompt":"Resize the billiard chalk cube to match its real size.","target":{"name":"Billiard chalk cube","dimension":"reference cube width","shape":"photo:chalk"},"reference":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses","measure":"14 cm · reference front width"},"bounds":[0.02,50],"answer":0.17857143,"explanation":"Billiard chalk cube: 0.025 m (reference cube width). Sunglasses: 0.14 m (reference front width). Ratio: 0.18×.\nA 2.5 cm chalk-cube reference.\nA 14 cm front-width reference, not the length of the folding arms.","sources":["https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png"]}]'::jsonb);
