erence":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder","measure":"32 cm · reference length"},"bounds":[0.02,50],"answer":0.264375,"explanation":"Game Boy Advance SP: 0.0846 m (console width). Soprano recorder: 0.32 m (reference length). Ratio: 0.26×.\nThe SP is 84.6 mm wide, whether open or closed.\nA 32 cm soprano recorder reference; recorders come in many sizes.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance_SP","https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://commons.wikimedia.org/wiki/File:Game-Boy-Advance-SP-Mk2.png","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png"]},{"id":"photo-size-v7-204","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"Game Boy Color","dimension":"console height","shape":"photo:gameboy-color","measure":"13.35 cm · console height"},"bounds":[0.02,50],"answer":0.98127341,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). Game Boy Color: 0.1335 m (console height). Ratio: 0.98×.\nT7M overall length: 131 mm.\nThe Game Boy Color is 133.5 mm high.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://en.wikipedia.org/wiki/Game_Boy_Color","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png"]},{"id":"photo-size-v7-205","version":7,"kind":"scale","prompt":"Resize the nikon d90 to match its real size.","target":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90"},"reference":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses","measure":"14 cm · reference front width"},"bounds":[0.02,50],"answer":0.94285714,"explanation":"Nikon D90: 0.132 m (camera body width). Sunglasses: 0.14 m (reference front width). Ratio: 0.94×.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.\nA 14 cm front-width reference, not the length of the folding arms.","sources":["https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',21,7,'[{"id":"photo-size-v7-206","version":7,"kind":"scale","prompt":"Resize the peacock butterfly to match its real size.","target":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly"},"reference":{"name":"Olympus E-PL1","dimension":"camera body width","shape":"photo:olympus","measure":"11.46 cm · camera body width"},"bounds":[0.02,50],"answer":0.56719023,"explanation":"Peacock butterfly: 0.065 m (reference wingspan). Olympus E-PL1: 0.1146 m (camera body width). Ratio: 0.57×.\nA 65 mm wingspan reference with the wings spread.\nE-PL1 body width: 114.6 mm.","sources":["https://butterfly-conservation.org/butterflies/peacock","https://en.wikipedia.org/wiki/Olympus_PEN_E-PL1","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png","https://commons.wikimedia.org/wiki/File:Olympus_E-PL1.png"]},{"id":"photo-size-v7-207","version":7,"kind":"scale","prompt":"Resize the european badger to match its real size.","target":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger"},"reference":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba","measure":"14.45 cm · console width"},"bounds":[0.02,50],"answer":5.19031142,"explanation":"European badger: 0.75 m (reference head-and-body length). Game Boy Advance: 0.1445 m (console width). Ratio: 5.19×.\nA 75 cm adult reference, excluding the tail. Adults vary in size.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.","sources":["https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://en.wikipedia.org/wiki/Game_Boy_Advance","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png"]},{"id":"photo-size-v7-208","version":7,"kind":"scale","prompt":"Resize the tennis ball to match its real size.","target":{"name":"Tennis ball","dimension":"reference ball diameter","shape":"photo:tennis-ball"},"reference":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller","measure":"12.3 cm · body width"},"bounds":[0.02,50],"answer":0.54471545,"explanation":"Tennis ball: 0.067 m (reference ball diameter). NES controller: 0.123 m (body width). Ratio: 0.54×.\nA 6.7 cm diameter reference, within the standard ball-size range.\nA 123 mm controller body reference; the cable is excluded.","sources":["https://www.itftennis.com/en/about-us/tennis-tech/approved-balls/","https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://commons.wikimedia.org/wiki/File:Tennisball2.png","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png"]},{"id":"photo-size-v7-209","version":7,"kind":"scale","prompt":"Resize the 2010 mac mini to match its real size.","target":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini"},"reference":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool","measure":"8 cm · reference overall height"},"bounds":[0.02,50],"answer":2.4625,"explanation":"2010 Mac mini: 0.197 m (enclosure width). Bicycle chain tool: 0.08 m (reference overall height). Ratio: 2.46×.\nThis Mac mini generation has a 19.7 cm square footprint.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.","sources":["https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png","https://commons.wikimedia.org/wiki/File:Chain_tool.png"]},{"id":"photo-size-v7-210","version":7,"kind":"scale","prompt":"Resize the dualshock 2 controller to match its real size.","target":{"name":"DualShock 2 controller","dimension":"reference controller width","shape":"photo:controller"},"reference":{"name":"Full-size electric guitar","dimension":"reference overall length","shape":"photo:guitar","measure":"1 m · reference overall length"},"bounds":[0.02,50],"answer":0.157,"explanation":"DualShock 2 controller: 0.157 m (reference controller width). Full-size electric guitar: 1 m (reference overall length). Ratio: 0.16×.\nA 15.7 cm controller-body width reference, excluding the cable.\nA one-metre reference guitar. Overall length varies by model; this is not its string scale length.","sources":["https://en.wikipedia.org/wiki/DualShock","https://www.fender.com/articles/instruments/what-is-scale-length","https://commons.wikimedia.org/wiki/File:PlayStation2-DualShock2.png","https://commons.wikimedia.org/wiki/File:Guitar_3.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',22,7,'[{"id":"photo-size-v7-211","version":7,"kind":"scale","prompt":"Resize the disposable razor to match its real size.","target":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor"},"reference":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote","measure":"14.5 cm · reference overall length"},"bounds":[0.02,50],"answer":0.68965517,"explanation":"Disposable razor: 0.1 m (reference overall length). Media remote control: 0.145 m (reference overall length). Ratio: 0.69×.\nA 10 cm razor reference, measured end to end.\nA 14.5 cm reference remote, measured end to end.","sources":["https://commons.wikimedia.org/wiki/File:Razor.png","https://www.playstation.com/en-us/accessories/media-remote/","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png"]},{"id":"photo-size-v7-212","version":7,"kind":"scale","prompt":"Resize the broccoli head to match its real size.","target":{"name":"Broccoli head","dimension":"reference overall height","shape":"photo:broccoli"},"reference":{"name":"Computer mouse","dimension":"reference body length","shape":"photo:sega-mouse","measure":"11 cm · reference body length"},"bounds":[0.02,50],"answer":1.81818182,"explanation":"Broccoli head: 0.2 m (reference overall height). Computer mouse: 0.11 m (reference body length). Ratio: 1.82×.\nA 20 cm broccoli reference including its stalk.\nAn 11 cm computer-mouse body reference; the cable is excluded.","sources":["https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png"]},{"id":"photo-size-v7-213","version":7,"kind":"scale","prompt":"Resize the open umbrella to match its real size.","target":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella"},"reference":{"name":"Concrete mixer truck","dimension":"reference overall length","shape":"photo:cement-truck","measure":"9 m · reference overall length"},"bounds":[0.02,50],"answer":0.11111111,"explanation":"Open umbrella: 1 m (reference canopy width). Concrete mixer truck: 9 m (reference overall length). Ratio: 0.11×.\nA one-metre canopy-width reference. Umbrella models vary.\nA nine-metre mixer-truck reference. Chassis and mixer configuration affect exact length.","sources":["https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Red_cement_mixer_truck.png"]},{"id":"photo-size-v7-214","version":7,"kind":"scale","prompt":"Resize the rolls-royce phantom iii to match its real size.","target":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce"},"reference":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute","measure":"67 cm · typical assembled length"},"bounds":[0.02,50],"answer":8.64179104,"explanation":"Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Concert flute: 0.67 m (typical assembled length). Ratio: 8.64×.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.\nA reference concert flute about 67 cm long; model and footjoint affect length.","sources":["https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png"]},{"id":"photo-size-v7-215","version":7,"kind":"scale","prompt":"Resize the city transit bus to match its real size.","target":{"name":"City transit bus","dimension":"40-foot bus length","shape":"photo:bus"},"reference":{"name":"Adult male giraffe","dimension":"upper adult height","shape":"photo:giraffe","measure":"5.5 m · upper adult height"},"bounds":[0.02,50],"answer":2.21818182,"explanation":"City transit bus: 12.2 m (40-foot bus length). Adult male giraffe: 5.5 m (upper adult height). Ratio: 2.22×.\nA nominal 40-foot (12.2 m) transit-bus reference; bumpers and model year affect exact length.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.","sources":["https://www.gillig.com/low-floor","https://animals.sandiegozoo.org/animals/giraffe","https://commons.wikimedia.org/wiki/File:Transparent_Santa_Cruz_Metro_bus_0222.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',23,7,'[{"id":"photo-size-v7-216","version":7,"kind":"scale","prompt":"Resize the f tuba to match its real size.","target":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba"},"reference":{"name":"Wire stripper","dimension":"reference overall length","shape":"photo:wire-stripper","measure":"17 cm · reference overall length"},"bounds":[0.02,50],"answer":5.29411765,"explanation":"F tuba: 0.9 m (reference standing height). Wire stripper: 0.17 m (reference overall length). Ratio: 5.29×.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.\nA 17 cm hand-tool reference. The photograph supplies the outline, not a scale calibration.","sources":["https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png","https://commons.wikimedia.org/wiki/File:Wire_stripper.png"]},{"id":"photo-size-v7-217","version":7,"kind":"scale","prompt":"Resize the three-cup moka pot to match its real size.","target":{"name":"Three-cup moka pot","dimension":"reference height","shape":"photo:coffee-pot"},"reference":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard","measure":"43 cm · keyboard-computer width"},"bounds":[0.02,50],"answer":0.37209302,"explanation":"Three-cup moka pot: 0.16 m (reference height). Commodore 128: 0.43 m (keyboard-computer width). Ratio: 0.37×.\nA roughly 16 cm three-cup reference. Moka pots are sold in many capacities.\nA 43 cm wide keyboard-computer reference.","sources":["https://www.bialetti.com/ee_en/moka-express.html","https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Moka_Express_sideview.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png"]},{"id":"photo-size-v7-218",