INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',29,7,'[{"id":"photo-size-v7-246","version":7,"kind":"scale","prompt":"Resize the city transit bus to match its real size.","target":{"name":"City transit bus","dimension":"40-foot bus length","shape":"photo:bus"},"reference":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute","measure":"67 cm · typical assembled length"},"bounds":[0.02,50],"answer":18.20895522,"explanation":"City transit bus: 12.2 m (40-foot bus length). Concert flute: 0.67 m (typical assembled length). Ratio: 18.21×.\nA nominal 40-foot (12.2 m) transit-bus reference; bumpers and model year affect exact length.\nA reference concert flute about 67 cm long; model and footjoint affect length.","sources":["https://www.gillig.com/low-floor","https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://commons.wikimedia.org/wiki/File:Transparent_Santa_Cruz_Metro_bus_0222.png","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png"]},{"id":"photo-size-v7-247","version":7,"kind":"scale","prompt":"Resize the f tuba to match its real size.","target":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba"},"reference":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":3,"explanation":"F tuba: 0.9 m (reference standing height). Land tortoise: 0.3 m (reference overall length). Ratio: 3.00×.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.","sources":["https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.