.org/wiki/File:Chain_tool.png"]},{"id":"photo-size-v7-305","version":7,"kind":"scale","prompt":"Resize the avocado to match its real size.","target":{"name":"Avocado","dimension":"reference fruit length","shape":"photo:avocado"},"reference":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight","measure":"13.1 cm · overall length"},"bounds":[0.02,50],"answer":1.06870229,"explanation":"Avocado: 0.14 m (reference fruit length). Ledlenser T7M flashlight: 0.131 m (overall length). Ratio: 1.07×.\nA 14 cm reference avocado. Fruit sizes vary considerably.\nT7M overall length: 131 mm.","sources":["https://commons.wikimedia.org/wiki/File:Avocado.png","https://www.ledlenser.my/product/flashlights/t7m/","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png"]}]'::jsonb);
