atch its real size.","target":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard"},"reference":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella","measure":"1 m · reference canopy width"},"bounds":[0.02,50],"answer":0.43,"explanation":"Commodore 128: 0.43 m (keyboard-computer width). Open umbrella: 1 m (reference canopy width). Ratio: 0.43×.\nA 43 cm wide keyboard-computer reference.\nA one-metre canopy-width reference. Umbrella models vary.","sources":["https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png","https://commons.wikimedia.org/wiki/File:Umbrella.png"]}]'::jsonb);
