intendo DS","dimension":"console width","shape":"photo:nintendo-ds"},"reference":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly","measure":"6.5 cm · reference wingspan"},"bounds":[0.02,50],"answer":2.28769231,"explanation":"Original Nintendo DS: 0.1487 m (console width). Peacock butterfly: 0.065 m (reference wingspan). Ratio: 2.29×.\nOriginal DS width: 148.7 mm.\nA 65 mm wingspan reference with the wings spread.","sources":["https://en.wikipedia.org/wiki/Nintendo_DS","https://butterfly-conservation.org/butterflies/peacock","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png"]}]'::jsonb);
