INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',66,7,'[{"id":"photo-size-v7-431","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba","measure":"14.45 cm · console width"},"bounds":[0.02,50],"answer":0.27681661,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). Game Boy Advance: 0.1445 m (console width). Ratio: 0.28×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://en.wikipedia.org/wiki/Game_Boy_Advance","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png"]},{"id":"photo-size-v7-432","version":7,"kind":"scale","prompt":"Resize the sony a5000 to match its real size.","target":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera"},"reference":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird","measure":"0.7 cm · reference body length"},"bounds":[0.02,50],"answer":15.65714286,"explanation":"Sony a5000: 0.1096 m (camera body width). Seven-spot ladybird: 0.007 m (reference body length). Ratio: 15.66×.\nSony a5000 body width: 109.6 mm.\nA 7 mm adult reference, excluding legs and antennae.","sources":["https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png"]},{"id":"photo-size-v7-433","version":7,"kind":"scale","prompt":"Re