","dimension":"reference height","shape":"photo:coffee-pot"},"reference":{"name":"BlackBerry Q10","dimension":"phone height","shape":"photo:blackberry","measure":"11.96 cm · phone height"},"bounds":[0.02,50],"answer":1.33779264,"explanation":"Three-cup moka pot: 0.16 m (reference height). BlackBerry Q10: 0.1196 m (phone height). Ratio: 1.34×.\nA roughly 16 cm three-cup reference. Moka pots are sold in many capacities.\nBlackBerry Q10 height: 119.6 mm.","sources":["https://www.bialetti.com/ee_en/moka-express.html","https://en.wikipedia.org/wiki/BlackBerry_Q10","https://commons.wikimedia.org/wiki/File:Moka_Express_sideview.png","https://commons.wikimedia.org/wiki/File:Blackberry-Q10-transparent.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',67,7,'[{"id":"photo-size-v7-436","version":7,"kind":"scale","prompt":"Resize the dreamcast vmu to match its real size.","target":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu"},"reference":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger","measure":"75 cm · reference head-and-body length"},"bounds":[0.02,50],"answer":0.10666667,"explanation":"Dreamcast VMU: 0.08 m (unit height). European badger: 0.75 m (reference head-and-body length). Ratio: 0.11×.\nThe Visual Memory Unit is about 80 mm high.\nA 75 cm adult reference, excluding the tail. Adults vary in size.","sources":["https://en.wikipedia.org/wiki/VMU","https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png"]},{"id":"photo-size-v7-437","version":7,"kind":"scale","prompt":"Resize the game boy advance sp to match its real size.","target":{"name":"Game Boy Advance SP","dimension":"console width","shape":"photo:gba-sp"},"reference":{"name":"Size-7 basketball","dimension":"nominal diameter","shape":"photo:basketball","measure":"23.9 cm · nominal diameter"},"bounds":[0.02,50],"answer":0.3539749,"explanation":"Game Boy Advance SP: 0.0846 m (console width). Size-7 basketball: 0.239 m (nominal diameter). Ratio: 0.35×.\nThe SP is 84.6 mm wide, whether open or closed.\nA nominal diameter of 23.9 cm, corresponding to about 75 cm circumference.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Advance_SP","https://www.fiba.basketball/en/official-basketball-rules","https://commons.wikimedia.org/wiki/File:Game-Boy-Advance-SP-Mk2.png","https://commons.wikimedia.org/wiki/File:Isolated_basketball.png"]},{"id":"photo-size-v7-438","version":7,"kind":"scale","prompt":"Resize the broccol