ecorder to match its real size.","target":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder"},"reference":{"name":"Original Nintendo DS","dimension":"console width","shape":"photo:nintendo-ds","measure":"14.87 cm · console width"},"bounds":[0.02,50],"answer":2.15198386,"explanation":"Soprano recorder: 0.32 m (reference length). Original Nintendo DS: 0.1487 m (console width). Ratio: 2.15×.\nA 32 cm soprano recorder reference; recorders come in many sizes.\nOriginal DS width: 148.7 mm.","sources":["https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://en.wikipedia.org/wiki/Nintendo_DS","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png"]},{"id":"photo-size-v7-504","version":7,"kind":"scale","prompt":"Resize the chameleon to match its real size.","target":{"name":"Chameleon","dimension":"reference overall length","shape":"photo:chameleon"},"reference":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card","measure":"2.5 cm · card width"},"bounds":[0.02,50],"answer":12,"explanation":"Chameleon: 0.3 m (reference overall length). xD-Picture Card: 0.025 m (card width). Ratio: 12.00×.\nA 30 cm reference specimen including the tail. Chameleon species vary widely.\nThe memory card is 25 mm wide and 20 mm high.","sources":["https://animals.sandiegozoo.org/animals/chameleon","https://en.wikipedia.org/wiki/XD-Picture_Card","https://commons.wikimedia.org/wiki/File:ChameleonCutOut.png","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png"]},{"id":"photo-size-v7-505","version":7,"kind":"scale","prompt":"Resize the billiard chalk cube to match its real size.","target":{"name":"Billiard chalk cube","dimension":"reference cube width","shape":"photo:chalk"},"reference":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90","measure":"13.2 cm · camera body width"},"bounds":[0.02,50],"answer":0.18939394,"explanation":"Billiard chalk cube: 0.025 m (reference cube width). Nikon D90: 0.132 m (camera body width). Ratio: 0.19×.\nA 2.5 cm chalk-cube reference.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.","sources":["https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',81,7,'[{"id":"photo-size-v7-506","version":7,"kind":"scale","prompt":"Resize the coffee bean to match its real size.","target":{"name":"Coffee bean","dimension":"reference long-axis length","shape":"photo:coffee-bean"},"reference":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba","measure":"14.45 cm · console width"},"bounds":[0.02,50],"answer":0.06920415,"explanation":"Coffee bean: 0.01 m (reference long-axis length). Game Boy Advance: 0.1445 m (console width). Ratio: 0.07×.\nA 10 mm roasted-coffee-bean reference.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.","sources":["https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://en.wikipedia.org/wiki/Game_Boy_Advance","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png"]},{"id":"photo-size-v7-507","version":7,"kind":"scale","prompt":"Resize the computer mouse to match its real size.","target":{"name":"Computer mouse","dimension":"reference body length","shape":"photo:sega-mouse"},"reference":{"name":"Tennis ball","dimension":"reference ball diameter","shape":"photo:tennis-ball","measure":"6.7 cm · reference ball diameter"},"bounds":[0.02,50],"answer":1.64179104,"explanation":"Computer mouse: 0.11 m (reference body length). Tennis ball: 0.067 m (reference ball diameter). Ratio: 1.64×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 6.7 cm diameter reference, within the standard ball-size range.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://www.itftennis.com/en/about-us/tennis-tech/approved-balls/","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Tennisball2.png"]},{"id":"photo-size-v7-508","version":7,"kind":"scale","prompt":"Resize the small scissors to match its real size.","target":{"name":"Small scissors","dimension":"reference end-to-end length","shape":"photo:scissors"},"reference":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller","measure":"12.3 cm · body width"},"bounds":[0.02,50],"answer":1.13821138,"explanation":"Small scissors: 0.14 m (reference end-to-end length). NES controller: 0.123 m (body width). Ratio: 1.14×.\nA 14 cm household-scissors reference, measured from handle end to blade tip.\nA 123 mm controller body reference; the cable is excluded.","sources":["https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png","https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png"]},{"id":"photo-size-v7-509","version":7,"kind":"scale","prompt":"Resize the road roller to match its real size.","target":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller"},"reference":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra","measure":"2.4 m · reference head-and-body length"},"bounds":[0.02,50],"answer":2.08333333,"explanation":"Road roller: 5 m (reference overall length). Plains zebra: 2.4 m (reference head-and-body length). Ratio: 2.08×.\nA five-metre road-roller reference; construction machines come in many sizes.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.","sources":["https://commons.wikimedia.org/wiki/File:Road_roller.png","https://animals.sandiegozoo.org/animals/zebra","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png"]},{"id":"photo-size-v7-510","version":7,"kind":"scale","prompt":"Resize the honda s2000 to match its real size.","target":{"name":"Honda S2000","dimension":"vehicle length","shape":"photo:honda-s2000"},"reference":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute","measure":"67 cm · typical assembled length"},"bounds":[0.02,50],"answer":6.17164179,"explanation":"Honda S2000: 4.135 m (vehicle length). Concert flute: 0.67 m (typical assembled length). Ratio: 6.17×.\n2005 S2000 overall length: 4.135 m.\nA reference concert flute about 67 cm long; model and footjoint affect length.","sources":["https://en.wikipedia.org/wiki/Honda_S2000","https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://commons.wikimedia.org/wiki/File:HondaS2000-004.png","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',82,7,'[{"id":"photo-size-v7-511","version":7,"kind":"scale","prompt":"Resize the land tortoise to match its real size.","target":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise"},"reference":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce","measure":"5.79 m · reference coachwork length"},"bounds":[0.02,50],"answer":0.05181347,"explanation":"Land tortoise: 0.3 m (reference overall length). Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Ratio: 0.05×.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.","sources":["https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png"]},{"id":"photo-size-v7-512","version":7,"kind":"scale","prompt":"Resize the broccoli head to match its real size.","target":{"name":"Broccoli head","dimension":"reference overall height","shape":"photo:broccoli"},"reference":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight","measure":"13.1 cm · overall length"},"bounds":[0.02,50],"answer":1.52671756,"explanation":"Broccoli head: 0.2 m (reference overall height). Ledlenser T7M flashlight: 0.131 m (overall length). Ratio: 1.53×.\nA 20 cm broccoli reference including its stalk.\nT7M overall length: 131 mm.","sources":["https://commons.wikimedia.org/wiki/File:Broccoli.png","https://www.ledlenser.my/product/flashlights/t7m/","https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashligh