INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',83,7,'[{"id":"photo-size-v7-516","version":7,"kind":"scale","prompt":"Resize the bicycle master-link pliers to match its real size.","target":{"name":"Bicycle master-link pliers","dimension":"reference overall length","shape":"photo:pliers"},"reference":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly","measure":"6.5 cm · reference wingspan"},"bounds":[0.02,50],"answer":2.61538462,"explanation":"Bicycle master-link pliers: 0.17 m (reference overall length). Peacock butterfly: 0.065 m (reference wingspan). Ratio: 2.62×.\nA 17 cm pliers reference; tool models differ.\nA 65 mm wingspan reference with the wings spread.","sources":["https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://butterfly-conservation.org/butterflies/peacock","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png"]},{"id":"photo-size-v7-517","version":7,"kind":"scale","prompt":"Resize the computer mouse to match its real size.","target":{"name":"Computer mouse","dimension":"reference body length","shape":"photo:sega-mouse"},"reference":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird","measure":"0.7 cm · reference body length"},"bounds":[0.02,50],"answer":15.71428571,"explanation":"Computer mouse: 0.11 m (reference body length). Seven-spot ladybird: 0.007 m (reference body length). Ratio: 15.71×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 7 mm adult reference, excluding legs and antennae.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png"]},{"id":