o:nintendo-ds","measure":"14.87 cm · console width"},"bounds":[0.02,50],"answer":1.07599193,"explanation":"Three-cup moka pot: 0.16 m (reference height). Original Nintendo DS: 0.1487 m (console width). Ratio: 1.08×.\nA roughly 16 cm three-cup reference. Moka pots are sold in many capacities.\nOriginal DS width: 148.7 mm.","sources":["https://www.bialetti.com/ee_en/moka-express.html","https://en.wikipedia.org/wiki/Nintendo_DS","https://commons.wikimedia.org/wiki/File:Moka_Express_sideview.png","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',92,7,'[{"id":"photo-size-v7-561","version":7,"kind":"scale","prompt":"Resize the peacock butterfly to match its real size.","target":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly"},"reference":{"name":"DualShock 2 controller","dimension":"reference controller width","shape":"photo:controller","measure":"15.7 cm · reference controller width"},"bounds":[0.02,50],"answer":0.41401274,"explanation":"Peacock butterfly: 0.065 m (reference wingspan). DualShock 2 controller: 0.157 m (reference controller width). Ratio: 0.41×.\nA 65 mm wingspan reference with the wings spread.\nA 15.7 cm controller-body width reference, excluding the cable.","sources":["https://butterfly-conservation.org/butterflies/peacock","https://en.wikipedia.org/wiki/DualShock","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png","https://commons.wikimedia.org/wiki/File:PlayStation2-DualShock2.png"]},{"id":"photo-size-v7-562","version":7,"kind":"scale","prompt":"Resize the chameleon to match its real size.","target":{"name":"Chameleon","dimension":"reference overall length","shape":"photo:chameleon"},"reference":{"name":"iPhone 3G","dimension":"phone height","shape":"photo:iphone3g","measure":"11.55 cm · phone height"},"bounds":[0.02,50],"answer":2.5974026,"explanation":"Chameleon: 0.3 m (reference overall length). iPhone 3G: 0.1155 m (phone height). Ratio: 2.60×.\nA 30 cm reference specimen including the tail. Chameleon species vary widely.\niPhone 3G height: 115.5 mm.","sources":["https://animals.sandiegozoo.org/animals/chameleon","https://devimages.apple.com/programs/ipod/dimensions/iPhone-3G-dimensions.pdf","https://commons.wikimedia.org/wiki/File:ChameleonCutOut.png","https://commons.wikimedia.org/wiki/File:IPhone_3G.png"]},{"id":"photo-size-v7-563","version":7,"kind":"scale","prompt":"Resize the small scissors to match its real size.","target":{"name":