":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera","measure":"10.96 cm · camera body width"},"bounds":[0.02,50],"answer":1.19525547,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). Sony a5000: 0.1096 m (camera body width). Ratio: 1.20×.\nT7M overall length: 131 mm.\nSony a5000 body width: 109.6 mm.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png"]},{"id":"photo-size-v7-574","version":7,"kind":"scale","prompt":"Resize the bicycle master-link pliers to match its real size.","target":{"name":"Bicycle master-link pliers","dimension":"reference overall length","shape":"photo:pliers"},"reference":{"name":"Atari Portfolio","dimension":"computer width","shape":"photo:calculator","measure":"20 cm · computer width"},"bounds":[0.02,50],"answer":0.85,"explanation":"Bicycle master-link pliers: 0.17 m (reference overall length). Atari Portfolio: 0.2 m (computer width). Ratio: 0.85×.\nA 17 cm pliers reference; tool models differ.\nThe pocket computer is about 20 cm wide.","sources":["https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://en.wikipedia.org/wiki/Atari_Portfolio","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:Atari-Portfolio-Computer.png"]},{"id":"photo-size-v7-575","version":7,"kind":"scale","prompt":"Resize the seven-spot ladybird to match its real size.","target":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird"},"reference":{"name":"Coffee bean","dimension":"reference long-axis length","shape":"photo:coffee-bean","measure":"1 cm · reference long-axis length"},"bounds":[0.02,50],"answer":0.7,"explanation":"Seven-spot ladybird: 0.007 m (reference body length). Coffee bean: 0.01 m (reference long-axis length). Ratio: 0.70×.\nA 7 mm adult reference, excluding legs and antennae.\nA 10 mm roasted-coffee-bean reference.","sources":["https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',95,7,'[{"id":"photo-size-v7-576","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"Olympus E-PL1","dimension":"camera body width","shape":"photo:olympus","measure":"11.46 cm · camera body width"},"bounds":[0.02,50],"answer":0.34904014,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). Olympus E-PL1: 0.1146 m (camera body width). Ratio: 0.35×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nE-PL1 body width: 114.6 mm.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://en.wikipedia.org/wiki/Olympus_PEN_E-PL1","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Olympus_E-PL1.png"]},{"id":"photo-size-v7-577","version":7,"kind":"scale","prompt":"Resize the rolls-royce phantom iii to match its real size.","target":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce"},"reference":{"name":"Full-size violin","dimension":"typical overall length","shape":"photo:violin","measure":"59 cm · typical overall length"},"bounds":[0.02,50],"answer":9.81355932,"explanation":"Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Full-size violin: 0.59 m (typical overall length). Ratio: 9.81×.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.\nA full-size violin is about 59 cm overall. The bow is excluded.","sources":["https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://www.yamaha.com/en/musical_instrument_guide/violin/structure/","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png","https://commons.wikimedia.org/wiki/File:Violin_VL100_(cropped).png"]},{"id":"photo-size-v7-578","version":7,"kind":"scale"