Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella"},"reference":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu","measure":"8 cm · unit height"},"bounds":[0.02,50],"answer":12.5,"explanation":"Open umbrella: 1 m (reference canopy width). Dreamcast VMU: 0.08 m (unit height). Ratio: 12.50×.\nA one-metre canopy-width reference. Umbrella models vary.\nThe Visual Memory Unit is about 80 mm high.","sources":["https://commons.wikimedia.org/wiki/File:Umbrella.png","https://en.wikipedia.org/wiki/VMU","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',96,7,'[{"id":"photo-size-v7-581","version":7,"kind":"scale","prompt":"Resize the climbing hammer to match its real size.","target":{"name":"Climbing hammer","dimension":"reference overall length","shape":"photo:climbing-hammer"},"reference":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro","measure":"10.1 cm · console width"},"bounds":[0.02,50],"answer":2.97029703,"explanation":"Climbing hammer: 0.3 m (reference overall length). Game Boy Micro: 0.101 m (console width). Ratio: 2.97×.\nA 30 cm hand-tool reference.\nThe Micro is 101 mm wide.","sources":["https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://en.wikipedia.org/wiki/Game_Boy_Micro","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png"]},{"id":"photo-size-v7-582","version":7,"kind":"scale","prompt":"Resize the soprano recorder to match its real size.","target":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder"},"reference":{"name":"BlackBerry Q10","dimension":"phone height","shape":"photo:blackberry","measure":"11.96 cm · phone height"},"bounds":[0.02,50],"answer":2.67558528,"explanation":"Soprano recorder: 0.32 m (reference length). BlackBerry Q10: 0.1196 m (phone height). Ratio: 2.68×.\nA 32 cm soprano recorder reference; recorders come in many sizes.\nBlackBerry Q10 height: 119.6 mm.","sources":["https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://en.wikipedia.org/wiki/BlackBerry_Q10","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png","https://commons.wikimedia.org/wiki/File:Blackberry-Q10-transparent.png"]},{"id":"photo-size-v7-583","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"pho