INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',101,7,'[{"id":"photo-size-v7-606","version":7,"kind":"scale","prompt":"Resize the sony a5000 to match its real size.","target":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera"},"reference":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":0.36533333,"explanation":"Sony a5000: 0.1096 m (camera body width). Land tortoise: 0.3 m (reference overall length). Ratio: 0.37×.\nSony a5000 body width: 109.6 mm.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.","sources":["https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png"]},{"id":"photo-size-v7-607","version":7,"kind":"scale","prompt":"Resize the kick scooter to match its real size.","target":{"name":"Kick scooter","dimension":"reference handlebar height","shape":"photo:skateboard"},"reference":{"name":"Nintendo Switch","dimension":"width with Joy-Con","shape":"photo:switch","measure":"23.9 cm · width with Joy-Con"},"bounds":[0.02,50],"answer":4.18410042,"explanation":"Kick scooter: 1 m (reference handlebar height). Nintendo Switch: 0.239 m (width with Joy-Con). Ratio: 4.18×.\nA one-metre handlebar-height reference. Adjustable scooters can be set lower.\nOriginal Nintendo Switch: 239 mm wide with Joy-Con attached.","sources":["https://www.stigasports.com/","https://www.nintendo.com/us/gaming-systems/switch/tech-specs/","https://commons.wikimedia.org/wiki/File:Stiga_Route_200_S.png","https://commons.wikimedia.org/wiki/File:Nintendo-Switch-wJoyCons-BlRd-Standing-FL.png"]},{"id