INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',106,7,'[{"id":"photo-size-v7-631","version":7,"kind":"scale","prompt":"Resize the bicycle master-link pliers to match its real size.","target":{"name":"Bicycle master-link pliers","dimension":"reference overall length","shape":"photo:pliers"},"reference":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote","measure":"14.5 cm · reference overall length"},"bounds":[0.02,50],"answer":1.17241379,"explanation":"Bicycle master-link pliers: 0.17 m (reference overall length). Media remote control: 0.145 m (reference overall length). Ratio: 1.17×.\nA 17 cm pliers reference; tool models differ.\nA 14.5 cm reference remote, measured end to end.","sources":["https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://www.playstation.com/en-us/accessories/media-remote/","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png"]},{"id":"photo-size-v7-632","version":7,"kind":"scale","prompt":"Resize the coffee bean to match its real size.","target":{"name":"Coffee bean","dimension":"reference long-axis length","shape":"photo:coffee-bean"},"reference":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu","measure":"8 cm · unit height"},"bounds":[0.02,50],"answer":0.125,"explanation":"Coffee bean: 0.01 m (reference long-axis length). Dreamcast VMU: 0.08 m (unit height). Ratio: 0.13×.\nA 10 mm roasted-coffee-bean reference.\nThe Visual Memory Unit is about 80 mm high.","sources":["https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://en.wikipedia.org/wiki/VMU","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png"]},{"id":"photo-size-v7-633","version":7,"kind":"scale","prompt":"Resize the sega nomad to match its real size.","tar