offee-bean"},"reference":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro","measure":"10.1 cm · console width"},"bounds":[0.02,50],"answer":0.0990099,"explanation":"Coffee bean: 0.01 m (reference long-axis length). Game Boy Micro: 0.101 m (console width). Ratio: 0.10×.\nA 10 mm roasted-coffee-bean reference.\nThe Micro is 101 mm wide.","sources":["https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://en.wikipedia.org/wiki/Game_Boy_Micro","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png"]}]'::jsonb);
