the akg c214 microphone to match its real size.","target":{"name":"AKG C214 microphone","dimension":"microphone height","shape":"photo:akg-microphone"},"reference":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba","measure":"90 cm · reference standing height"},"bounds":[0.02,50],"answer":0.17777778,"explanation":"AKG C214 microphone: 0.16 m (microphone height). F tuba: 0.9 m (reference standing height). Ratio: 0.18×.\nC214 microphone height: 160 mm, without a stand.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.","sources":["https://www.akg.com/Microphones/Condenser%20Microphones/C214.html","https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:AKG_C214_Condenser_microphone.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png"]},{"id":"photo-size-v7-729","version":7,"kind":"scale","prompt":"Resize the open umbrella to match its real size.","target":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella"},"reference":{"name":"Game Boy Advance","dimension":"console width","shape":"photo:gba","measure":"14.45 cm · console width"},"bounds":[0.02,50],"answer":6.92041522,"explanation":"Open umbrella: 1 m (reference canopy width). Game Boy Advance: 0.1445 m (console width). Ratio: 6.92×.\nA one-metre canopy-width reference. Umbrella models vary.\nOriginal model: 144.5 mm wide; cartridges are excluded from the width.","sources":["https://commons.wikimedia.org/wiki/File:Umbrella.png","https://en.wikipedia.org/wiki/Game_Boy_Advance","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:GameBoyAdvance-transparent.png"]},{"id":"photo-size-v7-730","version":7,"kind":"scale","prompt":"Resize the olympus e-pl1 to match its real size.","target":{"name":"Olympus E-PL1","dimension":"camera body width","shape":"photo:olympus"},"reference":{"name":"Three-cup moka pot","dimension":"reference height","shape":"photo:coffee-pot","measure":"16 cm · reference height"},"bounds":[0.02,50],"answer":0.71625,"explanation":"Olympus E-PL1: 0.1146 m (camera body width). Three-cup moka pot: 0.16 m (reference height). Ratio: 0.72×.\nE-PL1 body width: 114.6 mm.\nA roughly 16 cm three-cup reference. Moka pots are sold in many capacities.","sources":["https://en.wikipedia.org/wiki/Olympus_PEN_E-PL1","https://www.bialetti.com/ee_en/moka-express.html","https://commons.wikimedia.org/wiki/File:Olympus_E-PL1.png","https://commons.wikimedia.org/wiki/File:Moka_Express_sideview.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',126,7,'[{"id":"photo-size-v7-731","version":7,"kind":"scale","prompt":"Resize the iphone 3g to match its real size.","target":{"name":"iPhone 3G","dimension":"phone height","shape":"photo:iphone3g"},"reference":{"name":"Size-7 basketball","dimension":"nominal diameter","shape":"photo:basketball","measure":"23.9 cm · nominal diameter"},"bounds":[0.02,50],"answer":0.4832636,"explanation":"iPhone 3G: 0.1155 m (phone height). Size-7 basketball: 0.239 m (nominal diameter). Ratio: 0.48×.\niPhone 3G height: 115.5 mm.\nA nominal diameter of 23.9 cm, corresponding to about 75 cm circumference.","sources":["https://devimages.apple.com/programs/ipod/dimensions/iPhone-3G-dimensions.pdf","https://www.fiba.basketball/en/official-basketball-rules","https://commons.wikimedia.org/wiki/File:IPhone_3G.png","https://commons.wikimedia.org/wiki/File:Isolated_basketball.png"]},{"id":"photo-size-v7-732","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card","measure":"2.5 cm · card width"},"bounds":[0.02,50],"answer":5.24,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). xD-Picture Card: 0.025 m (card width). Ratio: 5.24×.\nT7M overall length: 131 mm.\nThe memory card is 25 mm wide and 20 mm high.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://en.wikipedia.org/wiki/XD-Picture_Card","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png"]},{"id":"photo-size-v7-733","version":7,"kind":"scale","prompt":"Resize the concert flute to match its real size.","target":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute"},"reference":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini","measure":"19.7 cm · enclosure width"},"bounds":[0.02,50],"answer":3.40101523,"explanation":"Concert flute: 0.67 m (typical assembled length). 2010 Mac mini: 0.197 m (enclosure width). Ratio: 3.40×.\nA reference concert flute about 67 cm long; model and footjoint affect length.\nThis Mac mini generation has a 19.7 cm square footprint.","sources":["https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png"]},{"id":"photo-size-v7-734","version":7,"kind":"scale","prompt":"Resize the computer mouse to match its real size.","target":{"name":"Computer mouse","dimension":"reference body length","shape":"photo:sega-mouse"},"reference":{"name":"Drywall screw","dimension":"reference screw length","shape":"photo:screw","measure":"3.5 cm · reference screw length"},"bounds":[0.02,50],"answer":3.14285714,"explanation":"Computer mouse: 0.11 m (reference body length). Drywall screw: 0.035 m (reference screw length). Ratio: 3.14×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 35 mm drywall-screw reference; this is one selected size, not a universal screw length.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Drywall_screw.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Drywall_screw.png"]},{"id":"photo-size-v7-735","version":7,"kind":"scale","prompt":"Resize the nikon d90 to match its real size.","target":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90"},"reference":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool","measure":"8 cm · reference overall height"},"bounds":[0.02,50],"answer":1.65,"explanation":"Nikon D90: 0.132 m (camera body width). Bicycle chain tool: 0.08 m (reference overall height). Ratio: 1.65×.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.","sources":["https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png","https://commons.wikimedia.org/wiki/File:Chain_tool.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',127,7,'[{"id":"photo-size-v7-736","version":7,"kind":"scale","prompt":"Resize the nes controller to match its real size.","target":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller"},"reference":{"name":"Wire stripper","dimension":"reference overall length","shape":"photo:wire-stripper","measure":"17 cm · reference overall length"},"bounds":[0.02,50],"answer":0.72352941,"explanation":"NES controller: 0.123 m (body width). Wire stripper: 0.17 m (reference overall length). Ratio: 0.72×.\nA 123 mm controller body reference; the cable is excluded.\nA 17 cm hand-tool reference. The photograph supplies the outline, not a scale calibration.","sources":["https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png","https://commons.wikimedia.org/wiki/File:Wire_stripper.png"]},{"id":"photo-size-v7-737","version":7,"kind":"scale","prompt":"Resize the sewing needle to match its real size.","target":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle"},"reference":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":0.13333333,"explanation":"Sewing needle: 0.04 m (reference end-to-end length). Land tortoise: 0.3 m (reference overall length). Ratio: 0.13×.\nA 4 cm reference needle. Sewing needles come in multiple lengths.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.","sources":["https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png"]},{"id":"photo-size-v7-738","version":7,"kind":"scale","prompt":"Resize the apple to match its real size.","target":{"name":"Apple","dimension":"reference fruit width","shape":"photo:apple"},"reference":{"name":"Small scissors","dimension":"reference end-to-end length","shape":"photo:scissors","measure":"14 cm · reference end-to-end length"},"bounds":[0.02,50],"answer":0.57142857,"explanation":"Apple: 0.08 m (reference fruit width). Small scissors: 0.14 m (reference end-to-end length). Ratio: 0.57×.\nAn 8 cm wide reference apple; real apples vary by cultivar and growing conditions.\nA 14 cm household-scissors reference, measured from handle end to blade tip.","sources":["https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png","https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png","https://commons.wikimedia.org/wiki/File:Small_pair_of_blue_scissors.png"]},{"id":"photo-size-v7-739","version":7,"kind":"scale","prompt":"Resize the disposable razor to match its real size.","target":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor"},"reference":{"name":"Tennis ball","dimension":"reference ball diameter","shape":"photo:tennis-ball","measure":"6.7 cm · reference ball diameter"},"bounds":[0.02,50],"answer":1.49253731,"explanation":"Disposable razor: 0.1 m (reference overall length). Tennis ball: 0.067 m (reference ball diameter). Ratio: 1.49×.\nA 10 cm razor reference, measured end to end.\nA 6.7 cm diameter reference, within the standard ball-size range.","sources":["https://commons.wikimedia.org/wiki/File:Razor.png","https://www.itftennis.com/en/about-us/tennis-tech/approved-balls/","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:Tennisball2.png"]},{"id":"photo-size-v7-740","version":7,"kind":"scale","prompt":"Resize the broccoli head to match its real size.","target":{"name":"Broccoli head","dimension":"reference overall height","shape":"photo:broccoli"},"reference":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder","measure":"32 cm · reference length"},"bounds":[0.02,50],"answer":0.625,"explanation":"Broccoli head: 0.2 m (reference overall height). Soprano recorder: 0.32 m (reference length). Ratio: 0.63×.\nA 20 cm broccoli reference including its stalk.\nA 32 cm soprano recorder reference; recorders come in many sizes.","sources":["https://commons.wikimedia.org/wiki/File:Broccoli.png","https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://commons.wikimedia.org/wiki/File:Broccoli.png","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',128,7,'[{"id":"photo-size-v7-741","version":7,"kind":"scale","prompt":"Resize the billiard chalk cube to match its real size.","target":{"name":"Billiard chalk cube","dimension":"reference cube width","shape":"photo:chalk"},"reference":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird","measure":"0.7 cm · reference body length"},"bounds":[0.02,50],"answer":3.57142857,"explanation":"Billiard chalk cube: 0.025 m (reference cube width). Seven-spot ladybird: 0.007 m (reference body length). Ratio: 3.57×.\nA 2.5 cm chalk-cube reference.\nA 7 mm adult reference, excluding legs and antennae.","sources":["https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://commons.wikimedia.org/wiki/File:Billiard_chalk_20050724.png","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png"]},{"id":"photo-size-v7-742","version":7,"kind":"scale","prompt":"Resize the avocado to match its real size.","target":{"name":"Avocado","dimension":"reference fruit length","shape":"photo:avocado"},"reference":{"name":"Game Boy Color","dimension":"console height","shape":"photo:gameboy-color","measure":"13.35 cm · console height"},"bounds":[0.02,50],"answer":1.04868914,"explanation":"Avocado: 0.14 m (reference fruit length). Game Boy Color: 0.1335 m (console height). Ratio: 1.05×.\nA 14 cm reference avocado. Fruit sizes vary considerably.\nThe Game Boy Color is 133.5 mm high.","sources":["https://commons.wikimedia.org/wiki/File:Avocado.png","https://en.wikipedia.org/wiki/Game_Boy_Color","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png"]},{"id":"photo-size-v7-743","version":7,"kind":"scale","prompt":"Resize the adult male giraffe to match its real size.","target":{"nam