","shape":"photo:avocado","measure":"14 cm · reference fruit length"},"bounds":[0.02,50],"answer":1.06214286,"explanation":"Original Nintendo DS: 0.1487 m (console width). Avocado: 0.14 m (reference fruit length). Ratio: 1.06×.\nOriginal DS width: 148.7 mm.\nA 14 cm reference avocado. Fruit sizes vary considerably.","sources":["https://en.wikipedia.org/wiki/Nintendo_DS","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:Nintendo-DS-Fat-Blue.png","https://commons.wikimedia.org/wiki/File:Avocado.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',140,7,'[{"id":"photo-size-v7-801","version":7,"kind":"scale","prompt":"Resize the adult male giraffe to match its real size.","target":{"name":"Adult male giraffe","dimension":"upper adult height","shape":"photo:giraffe"},"reference":{"name":"Open umbrella","dimension":"reference canopy width","shape":"photo:umbrella","measure":"1 m · reference canopy width"},"bounds":[0.02,50],"answer":5.5,"explanation":"Adult male giraffe: 5.5 m (upper adult height). Open umbrella: 1 m (reference canopy width). Ratio: 5.50×.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.\nA one-metre canopy-width reference. Umbrella models vary.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://commons.wikimedia.org/wiki/File:Umbrella.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png","https://commons.wikimedia.org/wiki/File:Umbrella.png"]},{"id":"photo-size-v7-802","version":7,"kind":"scale","prompt":"Resize the kick scooter to match its real size.","target":{"name":"Kick scooter","dimension":"reference handlebar height","shape":"photo:skateboard"},"reference":{"name":"Honda S2000","dimension":"vehicle length","shape":"photo:honda-s2000","measure":"4.135 m · vehicle length"},"bounds":[0.02,50],"answer":0.24183797,"explanation":"Kick scooter: 1 m (reference handlebar height). Honda S2000: 4.135 m (vehicle length). Ratio: 0.24×.\nA one-metre handlebar-height reference. Adjustable scooters can be set lower.\n2005 S2000 overall length: 4.135 m.","sources":["https://www.stigasports.com/","https://en.wikipedia.org/wiki/Honda_S2000","https://commons.wikimedia.org/wiki/File:Stiga_Route_200_S.png","https://commons.wikimedia.org/wiki/File:HondaS2000-004.png"]},{"id":"photo-size-v7-803","version":7,"kind":"scale","prompt":"Resize the seven-spot ladybird to match its real size.","target":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird"},"reference":{"name":"Game Boy Advance SP","dimension":"console width","shape":"photo:gba-sp","measure":"8.46 cm · console width"},"bounds":[0.02,50],"answer":0.08274232,"explanation":"Seven-spot ladybird: 0.007 m (reference body length). Game Boy Advance SP: 0.0846 m (console width). Ratio: 0.08×.\nA 7 mm adult reference, excluding legs and antennae.\nThe SP is 84.6 mm wide, whether open or closed.","sources":["https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://en.wikipedia.org/wiki/Game_Boy_Advance_SP","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Advance-SP-Mk2.png"]},{"id":"photo-size-v7-804","version":7,"kind":"scale","prompt":"Resize the road roller to match its real size.","target":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller"},"reference":{"name":"Full-size violin","dimension":"typical overall length","shape":"photo:violin","measure":"59 cm · typical overall length"},"bounds":[0.02,50],"answer":8.47457627,"explanation":"Road roller: 5 m (reference overall length). Full-size violin: 0.59 m (typical overall length). Ratio: 8.47×.\nA five-metre road-roller reference; construction machines come in many sizes.\nA full-size violin is about 59 cm overall. The bow is excluded.","sources":["https://commons.wikimedia.org/wiki/File:Road_roller.png","https://www.yamaha.com/en/musical_instrument_guide/violin/structure/","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Violin_VL100_(cropped).png"]},{"id":"photo-size-v7-805","version":7,"kind":"scale","prompt":"Resize the concert flute to match its real size.","target":{"name":"Concert flute","dimension":"typical assembled length","shape":"photo:flute"},"reference":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce","measure":"5.79 m · reference coachwork length"},"bounds":[0.02,50],"answer":0.11571675,"explanation":"Concert flute: 0.67 m (typical assembled length). Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Ratio: 0.12×.\nA reference concert flute about 67 cm long; model and footjoint affect length.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.","sources":["https://www.yamaha.com/en/musical_instrument_guide/flute/structure/","https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Yamaha_Flute_YFL-874W.png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',141,7,'[{"id":"photo-size-v7-806","version":7,"kind":"scale","prompt":"Resize the commodore 128 to match its real size.","target":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard"},"reference":{"name":"Chameleon","dimension":"reference overall length","shape":"photo:chameleon","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":1.43333333,"explanation":"Commodore 128: 0.43 m (keyboard-computer width). Chameleon: 0.3 m (reference overall length). Ratio: 1.43×.\nA 43 cm wide keyboard-computer reference.\nA 30 cm reference specimen including the tail. Chameleon species vary widely.","sources":["https://en.wikipedia.org/wiki/Commodore_128","https://animals.sandiegozoo.org/animals/chameleon","https://commons.wikimedia.org/wiki/File:Commodore-128.png","https://commons.wikimedia.org/wiki/File:ChameleonCutOut.png"]},{"id":"photo-size-v7-807","version":7,"kind":"scale","prompt":"Resize the climbing hammer to match its real size.","target":{"name":"Climbing hammer","dimension":"reference overall length","shape":"photo:climbing-hammer"},"reference":{"name":"iPhone 3G","dimension":"phone height","shape":"photo:iphone3g","measure":"11.55 cm · phone height"},"bounds":[0.02,50],"answer":2.5974026,"explanation":"Climbing hammer: 0.3 m (reference overall length). iPhone 3G: 0.1155 m (phone height). Ratio: 2.60×.\nA 30 cm hand-tool reference.\niPhone 3G height: 115.5 mm.","sources":["https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://devimages.apple.com/programs/ipod/dimensions/iPhone-3G-dimensions.pdf","https://commons.wikimedia.org/wiki/File:Climbing_hammer.png","https://commons.wikimedia.org/wiki/File:IPhone_3G.png"]},{"id":"photo-size-v7-808","version":7,"kind":"scale","prompt":"Resize the sony a5000 to match its real size.","target":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera"},"reference":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba","measure":"90 cm · reference standing height"},"bounds":[0.02,50],"answer":0.12177778,"explanation":"Sony a5000: 0.1096 m (camera body width). F tuba: 0.9 m (reference standing height). Ratio: 0.12×.\nSony a5000 body width: 109.6 mm.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.","sources":["https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png"]},{"id":"photo-size-v7-809","version":7,"kind":"scale","prompt":"Resize the european badger to match its real size.","target":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger"},"reference":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini","measure":"19.7 cm · enclosure width"},"bounds":[0.02,50],"answer":3.8071066,"explanation":"European badger: 0.75 m (reference head-and-body length). 2010 Mac mini: 0.197 m (enclosure width). Ratio: 3.81×.\nA 75 cm adult reference, excluding the tail. Adults vary in size.\nThis Mac mini generation has a 19.7 cm square footprint.","sources":["https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png"]},{"id":"photo-size-v7-810","version":7,"kind":"scale","prompt":"Resize the apple to match its real size.","target":{"name":"Apple","dimension":"reference fruit width","shape":"photo:apple"},"reference":{"name":"Game Boy Color","dimension":"console height","shape":"photo:gameboy-color","measure":"13.35 cm · console height"},"bounds":[0.02,50],"answer":0.59925094,"explanation":"Apple: 0.08 m (reference fruit width). Game Boy Color: 0.1335 m (console height). Ratio: 0.60×.\nAn 8 cm wide reference apple; real apples vary by cultivar and growing conditions.\nThe Game Boy Color is 133.5 mm high.","sources":["https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png","https://en.wikipedia.org/wiki/Game_Boy_Color","https://commons.wikimedia.org/wiki/File:Apple_in_lightbox.png","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',142,7,'[{"id":"photo-size-v7-811","version":7,"kind":"scale","prompt":"Resize the peacock butterfly to match its real size.","target":{"name":"Peacock butterfly","dimension":"reference wingspan","shape":"photo:peacock-butterfly"},"reference":{"name":"Atari Portfolio","dimension":"computer width","shape":"photo:calculator","measure":"20 cm · computer width"},"bounds":[0.02,50],"answer":0.325,"explanation":"Peacock butterfly: 0.065 m (reference wingspan). Atari Portfolio: 0.2 m (computer width). Ratio: 0.33×.\nA 65 mm wingspan reference with the wings spread.\nThe pocket computer is about 20 cm wide.","sources":["https://butterfly-conservation.org/butterflies/peacock","https://en.wikipedia.org/wiki/Atari_Portfolio","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png","https://commons.wikimedia.org/wiki/File:Atari-Portfolio-Computer.png"]},{"id":"photo-size-v7-812","version":7,"kind":"scale","prompt":"Resize the sunglasses to match its real size.","target":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses"},"reference":{"name":"Sega Nomad","dimension":"console width","shape":"photo:sega-nomad","measure":"18.5 cm · console width"},"bounds":[0.02,50],"answer":0.75675676,"explanation":"Sunglasses: 0.14 m (reference front width). Sega Nomad: 0.185 m (console width). Ratio: 0.76×.\nA 14 cm front-width reference, not the length of the folding arms.\nThe Nomad is approximately 18.5 cm wide.","sources":["https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://en.wikipedia.org/wiki/Genesis_Nomad","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Sega-Nomad-Front_(rotated).png"]},{"id":"photo-size-v7-813","version":7,"kind":"scale","prompt":"Resize the media remote control to match its real size.","target":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote"},"reference":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight","measure":"13.1 cm · overall length"},"bounds":[0.02,50],"answer":1.10687023,"explanation":"Media remote control: 0.145 m (reference overall length). Ledlenser T7M flashlight: 0.131 m (overall length). Ratio: 1.11×.\nA 14.5 cm reference remote, measured end to end.\nT7M overall length: 131 mm.","sources":["https://www.playstation.com/en-us/accessories/media-remote/","https://www.ledlenser.my/product/flashlights/t7m/","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png"]},{"id":"photo-size-v7-814","version":7,"kind":"scale","prompt":"Resize the soprano recorder to match its real size.","target":{"name":"Soprano recorder","dimension":"reference length","shape":"photo:recorder"},"reference":{"name":"Game Boy Micro","dimension":"console width","shape":"photo:gameboy-micro","measure":"10.1 cm · console width"},"bounds":[0.02,50],"answer":3.16831683,"explanation":"Soprano recorder: 0.32 m (reference length). Game Boy Micro: 0.101 m (console width). Ratio: 3.17×.\nA 32 cm soprano recorder reference; recorders come in many sizes.\nThe Micro is 101 mm wide.","sources":["https://www.yamaha.com/en/musical_instrument_guide/recorder/structure/","https://en.wikipedia.org/wiki/Game_Boy_Micro","https://commons.wikimedia.org/wiki/File:Yamaha_Soprano_Recorder_YRS-61.png","https://commons.wikimedia.org/wiki/File:Game-Boy-Micro.png"]},{"id":"photo-size-v7-815","version":7,"kind":"scale","prompt":"Resize the disposable razor to match its real size.","target":{"name":"Disposable razor","dimension":"reference overall length","shape":"photo:razor"},"reference":{"name":"AKG C214 microphone","dimension":"microphone height","shape":"photo:akg-microphone","measure":"16 cm · microphone height"},"bounds":[0.02,50],"answer":0.625,"explanation":"Disposable razor: 0.1 m (reference overall length). AKG C214 microphone: 0.16 m (microphone height). Ratio: 0.63×.\nA 10 cm razor reference, measured end to end.\nC214 microphone height: 160 mm, without a stand.","sources":["https://commons.wikimedia.org/wiki/File:Razor.png","https://www.akg.com/Microphones/Condenser%20Microphones/C214.html","https://commons.wikimedia.org/wiki/File:Razor.png","https://commons.wikimedia.org/wiki/File:AKG_C214_Condenser_microphone.png"]}]'::jsonb);
