:"reference body length","shape":"photo:sega-mouse"},"reference":{"name":"Bicycle master-link pliers","dimension":"reference overall length","shape":"photo:pliers","measure":"17 cm · reference overall length"},"bounds":[0.02,50],"answer":0.64705882,"explanation":"Computer mouse: 0.11 m (reference body length). Bicycle master-link pliers: 0.17 m (reference overall length). Ratio: 0.65×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 17 cm pliers reference; tool models differ.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Master_link_pliers.png"]},{"id":"photo-size-v7-824","version":7,"kind":"scale","prompt":"Resize the xd-picture card to match its real size.","target":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card"},"reference":{"name":"Land tortoise","dimension":"reference overall length","shape":"photo:tortoise","measure":"30 cm · reference overall length"},"bounds":[0.02,50],"answer":0.08333333,"explanation":"xD-Picture Card: 0.025 m (card width). Land tortoise: 0.3 m (reference overall length). Ratio: 0.08×.\nThe memory card is 25 mm wide and 20 mm high.\nA 30 cm overall-length reference including the head and legs. Species and poses vary.","sources":["https://en.wikipedia.org/wiki/XD-Picture_Card","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Tortoise.png"]},{"id":"photo-size-v7-825","version":7,"kind":"scale","prompt":"Resize the avocado to match its real size.","target":{"name":"Avocado","dimension":"reference fruit length","shape":"photo:avocado"},"reference":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90","measure":"13.2 cm · camera body width"},"bounds":[0.02,50],"answer":1.06060606,"explanation":"Avocado: 0.14 m (reference fruit length). Nikon D90: 0.132 m (camera body width). Ratio: 1.06×.\nA 14 cm reference avocado. Fruit sizes vary considerably.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.","sources":["https://commons.wikimedia.org/wiki/File:Avocado.png","https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Avocado.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png"]}]'::jsonb);
