re":"5.5 m · upper adult height"},"bounds":[0.02,50],"answer":0.18181818,"explanation":"Full-size electric guitar: 1 m (reference overall length). Adult male giraffe: 5.5 m (upper adult height). Ratio: 0.18×.\nA one-metre reference guitar. Overall length varies by model; this is not its string scale length.\nAn adult male can reach about 5.5 m tall. Individuals and poses vary.","sources":["https://www.fender.com/articles/instruments/what-is-scale-length","https://animals.sandiegozoo.org/animals/giraffe","https://commons.wikimedia.org/wiki/File:Guitar_3.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Giraffa.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',146,7,'[{"id":"photo-size-v7-831","version":7,"kind":"scale","prompt":"Resize the honda s2000 to match its real size.","target":{"name":"Honda S2000","dimension":"vehicle length","shape":"photo:honda-s2000"},"reference":{"name":"F tuba","dimension":"reference standing height","shape":"photo:tuba","measure":"90 cm · reference standing height"},"bounds":[0.02,50],"answer":4.59444444,"explanation":"Honda S2000: 4.135 m (vehicle length). F tuba: 0.9 m (reference standing height). Ratio: 4.59×.\n2005 S2000 overall length: 4.135 m.\nA 90 cm standing-height reference. Tubas vary substantially by pitch and design.","sources":["https://en.wikipedia.org/wiki/Honda_S2000","https://www.yamaha.com/en/musical_instrument_guide/tuba/structure/","https://commons.wikimedia.org/wiki/File:HondaS2000-004.png","https://commons.wikimedia.org/wiki/File:Viennese_six-valve_bass_tuba_in_F(made_by_Jungwirth)_Transparent.png"]},{"id":"photo-size-v7-832","version":7,"kind":"scale","prompt":"Resize the plains zebra to match its real size.","target":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra"},"reference":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote","measure":"14.5 cm · reference overall length"},"bounds":[0.02,50],"answer":16.55172414,"explanation":"Plains zebra: 2.4 m (reference head-and-body length). Media remote control: 0.145 m (reference overall length). Ratio: 16.55×.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.\nA 14.5 cm reference remote, measured end to end.","sources":["https://animals.sandiegozoo.org/animals/zebra","https://www.playstation.com/en-us/accessories/media-remote/","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png"]},{"id":"photo-size-v7-833","version":7,"kind":"scale","prompt":"Resize the seven-spot ladybird to match its real size.","target":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird"},"reference":{"name":"Game Boy Color","dimension":"console height","shape":"photo:gameboy-color","measure":"13.35 cm · console height"},"bounds":[0.02,50],"answer":0.05243446,"explanation":"Seven-spot ladybird: 0.007 m (reference body length). Game Boy Color: 0.1335 m (console height). Ratio: 0.05×.\nA 7 mm adult reference, excluding legs and antennae.\nThe Game Boy Color is 133.5 mm high.","sources":["https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://en.wikipedia.org/wiki/Game_Boy_Color","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png"]},{"id":"photo-size-v7-834","version":7,"kind":"scale","prompt":"Resize the road roller to match its real size.","target":{"name":"Road roller","dimension":"reference overall length","shape":"photo:road-roller"},"reference":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger","measure":"75 cm · reference head-and-body length"},"bounds":[0.02,50],"answer":6.66666667,"explanation":"Road roller: 5 m (reference overall length). European badger: 0.75 m (reference head-and-body length). Ratio: 6.67×.\nA five-metre road-roller reference; construction machines come in many sizes.\nA 75 cm adult reference, excluding the tail. Adults vary in size.","sources":["https://commons.wikimedia.org/wiki/File:Road_roller.png","https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://commons.wikimedia.org/wiki/File:Road_roller.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png"]},{"id":"photo-size-v7-835","version":7,"kind":"scale","prompt":"Resize the full-size violin to match its real size.","target":{"name":"Full-size violin","dimension":"typical overall length","shape":"photo:violin"},"reference":{"name":"Rolls-Royce Phantom III","dimension":"reference coachwork length","shape":"photo:rolls-royce","measure":"5.79 m · reference coachwork length"},"bounds":[0.02,50],"answer":0.10189983,"explanation":"Full-size violin: 0.59 m (typical overall length). Rolls-Royce Phantom III: 5.79 m (reference coachwork length). Ratio: 0.10×.\nA full-size violin is about 59 cm overall. The bow is excluded.\nA 5.79 m coachwork reference; bodies were made by different coachbuilders.","sources":["https://www.yamaha.com/en/musical_instrument_guide/violin/structure/","https://en.wikipedia.org/wiki/Rolls-Royce_Phantom_III","https://commons.wikimedia.org/wiki/File:Violin_VL100_(cropped).png","https://commons.wikimedia.org/wiki/File:Rolls_Royce_Phantom_III_1936_transparent.png"]}]'::jsonb);
