Game Boy Color: 0.1335 m (console height). Peacock butterfly: 0.065 m (reference wingspan). Ratio: 2.05×.\nThe Game Boy Color is 133.5 mm high.\nA 65 mm wingspan reference with the wings spread.","sources":["https://en.wikipedia.org/wiki/Game_Boy_Color","https://butterfly-conservation.org/butterflies/peacock","https://commons.wikimedia.org/wiki/File:Nintendo-Game-Boy-Color-FL.png","https://commons.wikimedia.org/wiki/File:Aglais_io_-_3150.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',151,7,'[{"id":"photo-size-v7-856","version":7,"kind":"scale","prompt":"Resize the wire stripper to match its real size.","target":{"name":"Wire stripper","dimension":"reference overall length","shape":"photo:wire-stripper"},"reference":{"name":"Plains zebra","dimension":"reference head-and-body length","shape":"photo:zebra","measure":"2.4 m · reference head-and-body length"},"bounds":[0.02,50],"answer":0.07083333,"explanation":"Wire stripper: 0.17 m (reference overall length). Plains zebra: 2.4 m (reference head-and-body length). Ratio: 0.07×.\nA 17 cm hand-tool reference. The photograph supplies the outline, not a scale calibration.\nA 2.4 m head-and-body reference; the tail is not part of this measurement.","sources":["https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://animals.sandiegozoo.org/animals/zebra","https://commons.wikimedia.org/wiki/File:Wire_stripper.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Zebra.png"]},{"id":"photo-size-v7-857","version":7,"kind":"scale","prompt":"Resize the commodore 128 to match its real size.","target":{"name":"Commodore 128","dimension":"keyboard-computer width","shape":"photo:keyboard"},"reference":{"name":"Sewing needle","dimension":"reference end-to-end length","shape":"photo:needle","measure":"4 cm · reference end-to-end length"},"bounds":[0.02,50],"answer":10.75,"explanation":"Commodore 128: 0.43 m (keyboard-computer width). Sewing needle: 0.04 m (reference end-to-end length). Ratio: 10.75×.\nA 43 cm wide keyboard-computer reference.\nA 4 cm reference needle. Sewing needles come in multiple lengths.","sources":["https://en.wikipedia.org/wiki/Commodore_128","https://commons.wikimedia.org/wiki/File:Sewing_needle.png","https://commons.wikimedia.org/wiki/File:Commodore-128.png","https://commons.wikimedia.org/wiki/File:Sewing_needle.png"]},{"id":"photo-size-v7-858","version":7,"kind"