INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',152,7,'[{"id":"photo-size-v7-861","version":7,"kind":"scale","prompt":"Resize the media remote control to match its real size.","target":{"name":"Media remote control","dimension":"reference overall length","shape":"photo:remote"},"reference":{"name":"Kick scooter","dimension":"reference handlebar height","shape":"photo:skateboard","measure":"1 m · reference handlebar height"},"bounds":[0.02,50],"answer":0.145,"explanation":"Media remote control: 0.145 m (reference overall length). Kick scooter: 1 m (reference handlebar height). Ratio: 0.14×.\nA 14.5 cm reference remote, measured end to end.\nA one-metre handlebar-height reference. Adjustable scooters can be set lower.","sources":["https://www.playstation.com/en-us/accessories/media-remote/","https://www.stigasports.com/","https://commons.wikimedia.org/wiki/File:PlayStation_5_Media_Remote_-_front.png","https://commons.wikimedia.org/wiki/File:Stiga_Route_200_S.png"]},{"id":"photo-size-v7-862","version":7,"kind":"scale","prompt":"Resize the bicycle chain tool to match its real size.","target":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool"},"reference":{"name":"Sony a5000","dimension":"camera body width","shape":"photo:sony-camera","measure":"10.96 cm · camera body width"},"bounds":[0.02,50],"answer":0.72992701,"explanation":"Bicycle chain tool: 0.08 m (reference overall height). Sony a5000: 0.1096 m (camera body width). Ratio: 0.73×.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.\nSony a5000 body width: 109.6 mm.","sources":["https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://www.sony.com/electronics/interchangeable-lens-cameras/ilce-5000-kit/specifications","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:Sony_A5000_white.png"]},{"id":"photo-size-v7-863","version":7,"kind":"scale","pro