.02,50],"answer":11,"explanation":"Computer mouse: 0.11 m (reference body length). Coffee bean: 0.01 m (reference long-axis length). Ratio: 11.00×.\nAn 11 cm computer-mouse body reference; the cable is excluded.\nA 10 mm roasted-coffee-bean reference.","sources":["https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-Mouse-BR.png","https://commons.wikimedia.org/wiki/File:Coffee_bean_transparent.png"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',157,7,'[{"id":"photo-size-v7-886","version":7,"kind":"scale","prompt":"Resize the honda s2000 to match its real size.","target":{"name":"Honda S2000","dimension":"vehicle length","shape":"photo:honda-s2000"},"reference":{"name":"European badger","dimension":"reference head-and-body length","shape":"photo:badger","measure":"75 cm · reference head-and-body length"},"bounds":[0.02,50],"answer":5.51333333,"explanation":"Honda S2000: 4.135 m (vehicle length). European badger: 0.75 m (reference head-and-body length). Ratio: 5.51×.\n2005 S2000 overall length: 4.135 m.\nA 75 cm adult reference, excluding the tail. Adults vary in size.","sources":["https://en.wikipedia.org/wiki/Honda_S2000","https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/animals/mammals/badger/","https://commons.wikimedia.org/wiki/File:HondaS2000-004.png","https://commons.wikimedia.org/wiki/File:Animals_png_set_by_mossi889-d4uye4q_-_Badger.png"]},{"id":"photo-size-v7-887","version":7,"kind":"scale","prompt":"Resize the nes controller to match its real size.","target":{"name":"NES controller","dimension":"body width","shape":"photo:nes-controller"},"reference":{"name":"Seven-spot ladybird","dimension":"reference body length","shape":"photo:ladybird","measure":"0.7 cm · reference body length"},"bounds":[0.02,50],"answer":17.57142857,"explanation":"NES controller: 0.123 m (body width). Seven-spot ladybird: 0.007 m (reference body length). Ratio: 17.57×.\nA 123 mm controller body reference; the cable is excluded.\nA 7 mm adult reference, excluding legs and antennae.","sources":["https://en.wikipedia.org/wiki/Nintendo_Entertainment_System","https://www.wildlifetrusts.org/wildlife-explorer/invertebrates/beetles/7-spot-ladybird","https://commons.wikimedia.org/wiki/File:Nintendo-Entertainment-System-NES-Controller-FL.png","https://commons.wikimedia.org/wiki/File:Coccinella-septempunctata--Trp-1.png"]},{"id":"photo-s