INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',166,7,'[{"id":"photo-size-v7-931","version":7,"kind":"scale","prompt":"Resize the sunglasses to match its real size.","target":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses"},"reference":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90","measure":"13.2 cm · camera body width"},"bounds":[0.02,50],"answer":1.06060606,"explanation":"Sunglasses: 0.14 m (reference front width). Nikon D90: 0.132 m (camera body width). Ratio: 1.06×.\nA 14 cm front-width reference, not the length of the folding arms.\nD90 body width: 132 mm. Lens and strap are not part of the width measurement.","sources":["https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://www.nikon.com/company/news/2008/0827_d90_01/","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Nikon_D90.png"]},{"id":"photo-size-v7-932","version":7,"kind":"scale","prompt":"Resize the xd-picture card to match its real size.","target":{"name":"xD-Picture Card","dimension":"card width","shape":"photo:xd-card"},"reference":{"name":"Bicycle chain tool","dimension":"reference overall height","shape":"photo:chain-tool","measure":"8 cm · reference overall height"},"bounds":[0.02,50],"answer":0.3125,"explanation":"xD-Picture Card: 0.025 m (card width). Bicycle chain tool: 0.08 m (reference overall height). Ratio: 0.31×.\nThe memory card is 25 mm wide and 20 mm high.\nAn 8 cm portable chain-tool reference, excluding the length of any loose chain.","sources":["https://en.wikipedia.org/wiki/XD-Picture_Card","https://commons.wikimedia.org/wiki/File:Chain_tool.png","https://commons.wikimedia.org/wiki/File:XD_card_16M_Fujifilm_front.png","https://commons.wikimedia.org/wiki/File:Chain_tool.png"]},{"id":"photo-size-v7-933","version":7,"kind":"scale","prompt":"Resize the game boy advance to match its real size.","targ