INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',171,7,'[{"id":"photo-size-v7-956","version":7,"kind":"scale","prompt":"Resize the ledlenser t7m flashlight to match its real size.","target":{"name":"Ledlenser T7M flashlight","dimension":"overall length","shape":"photo:flashlight"},"reference":{"name":"2010 Mac mini","dimension":"enclosure width","shape":"photo:mac-mini","measure":"19.7 cm · enclosure width"},"bounds":[0.02,50],"answer":0.66497462,"explanation":"Ledlenser T7M flashlight: 0.131 m (overall length). 2010 Mac mini: 0.197 m (enclosure width). Ratio: 0.66×.\nT7M overall length: 131 mm.\nThis Mac mini generation has a 19.7 cm square footprint.","sources":["https://www.ledlenser.my/product/flashlights/t7m/","https://support.apple.com/en-us/112588","https://commons.wikimedia.org/wiki/File:LED_LENSER_T7M_LED_flashlight.png","https://commons.wikimedia.org/wiki/File:Mac_mini_server.png"]},{"id":"photo-size-v7-957","version":7,"kind":"scale","prompt":"Resize the dreamcast vmu to match its real size.","target":{"name":"Dreamcast VMU","dimension":"unit height","shape":"photo:dreamcast-vmu"},"reference":{"name":"Sunglasses","dimension":"reference front width","shape":"photo:sunglasses","measure":"14 cm · reference front width"},"bounds":[0.02,50],"answer":0.57142857,"explanation":"Dreamcast VMU: 0.08 m (unit height). Sunglasses: 0.14 m (reference front width). Ratio: 0.57×.\nThe Visual Memory Unit is about 80 mm high.\nA 14 cm front-width reference, not the length of the folding arms.","sources":["https://en.wikipedia.org/wiki/VMU","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png","https://commons.wikimedia.org/wiki/File:Sega-Dreamcast-VMU.png","https://commons.wikimedia.org/wiki/File:Sunglasses-1_retouch.png"]},{"id":"photo-size-v7-958","version":7,"kind":"scale","prompt":"Resize the nikon d90 to match its real size.","target":{"name":"Nikon D90","dimension":"camera body width","shape":"photo:nikon-d90"},"r